const APP = {
  bootstrap: null,
  role: sessionStorage.getItem('sasj-role') || null,
  page: 'dashboard',
  schedule: { date: (()=>{ const d=new Date(); const pad=n=>String(n).padStart(2,'0'); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; })(), lab: 'Both', view: 'day', classFilter: 'All' },
  bookingStatus: { search: '', status: 'All' },
  scrollToBookingStatus: false,
};

const DAYS = ['Mon','Tue','Wed','Thu','Fri'];
const ROLE_LABELS = {
  teacher: 'Science Teacher',
  hod: 'Science HOD / SH',
  labtech: 'Lab Technician',
  admin: 'System Admin',
};

const NAV = [
  { id: 'dashboard', icon: '⌂', label: 'Dashboard', roles: ['teacher','hod','labtech','admin'] },
  { id: 'schedule', icon: '▦', label: 'Lab Schedule', roles: ['teacher','hod','labtech','admin'] },
  { id: 'request', icon: '+', label: 'Create Booking', roles: ['teacher','hod','labtech','admin'] },
  { id: 'inventory', icon: '□', label: 'Inventory', roles: ['teacher','hod','labtech','admin'] },
  { id: 'approvals', icon: '✓', label: 'Requests & Approvals', roles: ['labtech','admin','hod'] },
  { id: 'timetable', icon: '↻', label: 'Timetable Organizer', roles: ['hod','admin'] },
  { id: 'roster', icon: '♙', label: 'Teacher Deployment', roles: ['hod','admin'] },
  { id: 'settings', icon: '⚙', label: 'Administration', roles: ['admin','hod'] },
];

const PAGE_META = {
  dashboard: ['Dashboard', 'At-a-glance lab operations'],
  schedule: ['Lab Schedule', 'View, confirm, amend and monitor lab bookings'],
  request: ['Create Booking', 'Create an additional lab booking or reserve a lab for a special event'],
  inventory: ['Inventory', 'Live stock, kits, missing components and photos'],
  approvals: ['Requests & Approvals', 'Review pending requests and resolve conflicts before approval'],
  timetable: ['Timetable Organizer', 'Import, optimise, review and publish timetable versions'],
  roster: ['Teacher Deployment', 'Science manpower, level deployment and special teaching groups'],
  settings: ['Administration', 'Operational rules and system settings'],
};

function clone(v){ return JSON.parse(JSON.stringify(v)); }
function esc(value=''){ return String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function uid(prefix='id'){ return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`; }
function minutes(t){ const [h,m]=String(t).split(':').map(Number); return h*60+m; }
function endAfterHour(start){ const total=minutes(start)+60; return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`; }
function fmtTime(t){ const [h,m]=String(t).split(':').map(Number); const suffix=h>=12?'PM':'AM'; const hh=((h+11)%12)+1; return `${hh}:${String(m).padStart(2,'0')} ${suffix}`; }
function parseISODate(iso){ return new Date(`${iso}T12:00:00`); }
function isoDate(d){ const pad=n=>String(n).padStart(2,'0'); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; }
function addDaysISO(iso,days){ const d=parseISODate(iso); d.setDate(d.getDate()+days); return isoDate(d); }
function mondayISO(iso){ const d=parseISODate(iso); const dow=d.getDay(); d.setDate(d.getDate()-(dow===0?6:dow-1)); return isoDate(d); }
function dayCodeFromDate(iso){ return ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][parseISODate(iso).getDay()]; }
function weekParityFromDate(iso){ const ref=mondayISO(settings().odd_week_reference_monday||'2026-09-07'); const mon=mondayISO(iso); const weeks=Math.round((parseISODate(mon)-parseISODate(ref))/(7*24*60*60*1000)); return ((weeks%2)+2)%2===0?'Odd':'Even'; }
function formatDateLong(iso){ return parseISODate(iso).toLocaleDateString('en-SG',{weekday:'long',day:'numeric',month:'short',year:'numeric'}); }
function formatDateShort(iso){ return parseISODate(iso).toLocaleDateString('en-SG',{day:'numeric',month:'short'}); }
function weekRangeLabel(iso){ const mon=mondayISO(iso),fri=addDaysISO(mon,4); return `${formatDateShort(mon)}–${formatDateShort(fri)} ${parseISODate(fri).getFullYear()}`; }
function dateFromLegacyWeekDay(week,day,anchorISO=APP.schedule.date){ const mon=mondayISO(anchorISO); for(let offset=-14;offset<=14;offset+=7){ const candidateMon=addDaysISO(mon,offset); if(weekParityFromDate(candidateMon)!==week)continue; const idx=DAYS.indexOf(day); if(idx>=0)return addDaysISO(candidateMon,idx); } return mon; }
function confirmationDeadlineDate(date){ const deadline=new Date(`${addDaysISO(date,-1)}T${settings().confirmation_deadline||'14:00'}:00`); return deadline; }
function activityLabel(raw){
  const text=String(raw||'').trim(); if(!text) return '';
  const m=text.match(/(?:activity\s*)?(\d+(?:\.\d+)+)/i);
  return m ? `Activity ${m[1]}` : text.replace(/^activity\s*/i,'Activity ');
}
function roleCanEditInventory(){ return ['labtech','hod','admin'].includes(APP.role); }
function roleCanApprove(){ return ['labtech','hod','admin'].includes(APP.role); }
function roleCanDirectBook(){ return ['hod','admin','labtech'].includes(APP.role); }
function readLocal(key, fallback){ try{ const v=localStorage.getItem(key); return v?JSON.parse(v):clone(fallback); }catch{return clone(fallback);} }
function writeLocal(key, value){ localStorage.setItem(key, JSON.stringify(value)); }
function data(){ return APP.bootstrap; }
function teachers(){ return readLocal('sasj-v07-teachers', data().teachers); }
function inventory(){ return readLocal('sasj-v07-inventory', data().inventory); }
function requests(){ return readLocal('sasj-v07-requests', data().requests); }
function settings(){ return readLocal('sasj-v07-settings', data().settings); }
function specialGroups(){ return readLocal('sasj-v07-special-groups', data().special_groups||[]); }
function blockouts(){ return readLocal('sasj-v07-blockouts', data().blockouts||[]); }
function auditLogs(){ return readLocal('sasj-v07-audit', data().audit_logs||[]); }
function recordAudit(action,detail=''){ const arr=auditLogs(); arr.unshift({when:new Date().toLocaleString('en-SG'),who:ROLE_LABELS[APP.role]||'System',action,detail}); writeLocal('sasj-v07-audit',arr.slice(0,200)); }
function academicCalendar(year){ return data().academic_calendars?.[String(year)]||null; }
function sessionActions(){ return readLocal('sasj-v07-session-actions', data().session_actions||{}); }
function teacherNamesForClass(className){ return teachers().filter(t=>(t.classes||[]).includes(className)).map(t=>t.name); }
function clearPrototypeData(){ ['sasj-v07-teachers','sasj-v07-inventory','sasj-v07-requests','sasj-v07-settings','sasj-v07-session-actions','sasj-v07-special-groups','sasj-v07-blockouts','sasj-v07-audit'].forEach(k=>localStorage.removeItem(k)); }
function sessionKey(a){ return [a.class_name,a.week,a.day,a.lab,a.start_time].join('|'); }
function crestUrl(){ return data()?.app?.crest_url || 'assets/sasj-crest-clean.webp'; }
function requestTypeLabel(type){ return ({additional:'Ad hoc booking',event:'Special event / workshop',amendment:'Amendment request'})[type] || type; }
function displayRequestStatus(r){ if(r.status==='Approved' && r.request_type!=='amendment') return 'Confirmed'; return r.status; }
function statusClass(status){
  const s=String(status||'').toLowerCase();
  if(['confirmed','approved','good'].includes(s)) return 'confirmed';
  if(['pre-assigned','preassigned'].includes(s)) return 'preassigned';
  if(['pending'].includes(s)) return 'pending';
  if(['rejected','cancelled','released','missing'].includes(s)) return 'rejected';
  return 'info';
}
function timeOptions(selected='07:30'){
  let html='';
  for(let t=7*60+30;t<=13*60;t+=30){
    const v=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;
    html+=`<option value="${v}" ${v===selected?'selected':''}>${fmtTime(v)}–${fmtTime(endAfterHour(v))}</option>`;
  }
  return html;
}

function allocationKey(a){ return [a.class_name,a.week,a.day,a.lab,a.start_time].join('|'); }
function sessionKey(a){ return allocationKey(a); }
function occurrenceKey(a,date){ return `${allocationKey(a)}@@${date}`; }
function baselineAction(key){ return sessionActions()[key] || {}; }
function requestDate(r){ return r.date || dateFromLegacyWeekDay(r.week,r.day,APP.schedule.date); }
function resolveBaseline(a){
  const originalKey=allocationKey(a);
  return {
    ...clone(a), source_kind:'baseline', source_id:originalKey, original_key:originalKey,
    status:'Pre-assigned', teacher:teacherNamesForClass(a.class_name).join(' / '),
    activity:'', sets:'', apparatus:'', remarks:'', booking_type:'Pre-assigned',
  };
}
function baselineEntries(includeInactive=false){ return data().baseline_schedule.allocations.map(resolveBaseline); }
function baselineOccurrence(a,date){
  const key=occurrenceKey(a,date), action=baselineAction(key), now=new Date();
  const status=action.status || (settings().auto_release_preassigned_only && now>confirmationDeadlineDate(date) ? 'Released' : 'Pre-assigned');
  return {
    ...clone(a), source_kind:'baseline', source_id:key, original_key:allocationKey(a), instance_key:key,
    original_date:date, date:action.date||date,
    week:weekParityFromDate(action.date||date), day:dayCodeFromDate(action.date||date),
    lab:action.lab||a.lab, start_time:action.start_time||a.start_time, end_time:action.end_time||a.end_time,
    status, teacher:action.teacher||teacherNamesForClass(a.class_name).join(' / '),
    activity:action.activity||'', sets:action.sets||'', apparatus:action.apparatus||'', remarks:action.remarks||'',
    booking_type:'Pre-assigned',
  };
}
function baselineOccurrencesForDate(date,includeInactive=false){
  const week=weekParityFromDate(date), day=dayCodeFromDate(date), out=[];
  data().baseline_schedule.allocations.filter(a=>a.week===week&&a.day===day).forEach(a=>{
    const e=baselineOccurrence(a,date); if(e.date===date && (includeInactive||!['Cancelled','Released'].includes(e.status))) out.push(e);
  });
  const actions=sessionActions(); Object.entries(actions).forEach(([key,action])=>{
    if(!key.includes('@@')||!action.date||action.date!==date||action.original_date===date)return;
    const alloc=data().baseline_schedule.allocations.find(a=>allocationKey(a)===action.allocation_key); if(!alloc)return;
    const e=baselineOccurrence(alloc,action.original_date); if(includeInactive||!['Cancelled','Released'].includes(e.status)) out.push(e);
  });
  return out;
}
function requestEntry(r){
  const date=requestDate(r);
  return {...clone(r), date, week:weekParityFromDate(date), day:dayCodeFromDate(date), source_kind:'request', source_id:r.id, booking_type:requestTypeLabel(r.request_type), display_status:displayRequestStatus(r)};
}
function approvedRequestEntriesForDate(date){ return requests().filter(r=>r.status==='Approved'&&r.request_type!=='amendment'&&requestDate(r)===date).map(requestEntry); }
function pendingRequestEntriesForDate(date){ return requests().filter(r=>r.status==='Pending'&&requestDate(r)===date).map(requestEntry); }
function activeApprovedRequestEntries(){ return requests().filter(r=>r.status==='Approved'&&r.request_type!=='amendment').map(requestEntry); }
function activeOfficialEntries(){ return [...baselineEntries(false), ...activeApprovedRequestEntries()]; }
function activeOfficialEntriesForDate(date){ return [...baselineOccurrencesForDate(date,false), ...approvedRequestEntriesForDate(date)]; }
function baselineOccurrencesForWeek(anchor,includeInactive=false){ const mon=mondayISO(anchor),out=[]; for(let i=0;i<5;i++)out.push(...baselineOccurrencesForDate(addDaysISO(mon,i),includeInactive)); return out; }
function activeOfficialEntriesInWindow(anchor,weeks=4){ const mon=mondayISO(anchor),out=[]; for(let i=0;i<weeks*7;i++){const d=addDaysISO(mon,i);if(DAYS.includes(dayCodeFromDate(d)))out.push(...activeOfficialEntriesForDate(d));} return out; }
function pendingRequestEntries(){ return requests().filter(r=>r.status==='Pending').map(requestEntry); }
function entryRef(entry){ return `${entry.source_kind}:${entry.source_id}`; }
function overlaps(a,b){
  const sameDate=a.date&&b.date ? a.date===b.date : (a.week===b.week&&a.day===b.day);
  return sameDate && a.lab===b.lab && minutes(a.start_time)<minutes(b.end_time) && minutes(a.end_time)>minutes(b.start_time);
}
function excludedByOriginal(candidate,official){ return candidate.request_type==='amendment'&&candidate.original_kind===official.source_kind&&candidate.original_id===official.source_id; }
function blockoutConflictEntries(date){return blockouts().filter(b=>b.active!==false&&date>=b.start_date&&date<=b.end_date).flatMap(b=>{const labs=b.lab==='Both'?['Lab 1','Lab 2']:[b.lab];return labs.map(lab=>({source_kind:'blockout',source_id:b.id,class_name:`Blocked: ${b.reason}`,teacher:'HOD / Admin',date,week:weekParityFromDate(date),day:dayCodeFromDate(date),lab,start_time:'00:00',end_time:'23:59',status:'Confirmed',booking_type:'Lab block-out'}));});}
function findOfficialConflicts(candidate,excludeRef=''){
  const pool=candidate.date?[...activeOfficialEntriesForDate(candidate.date),...blockoutConflictEntries(candidate.date)]:activeOfficialEntries();
  return pool.filter(e=>entryRef(e)!==excludeRef&&!excludedByOriginal(candidate,e)&&overlaps(candidate,e));
}
function conflictsForPending(r){ return findOfficialConflicts(requestEntry(r)); }
function pendingWarningsForEntry(entry){
  const pool=entry.date?pendingRequestEntriesForDate(entry.date):pendingRequestEntries();
  return pool.filter(r=>!excludedByOriginal(r,entry)&&overlaps(r,entry));
}
function officialConflictPairs(){
  const entries=activeOfficialEntries(),pairs=[]; for(let i=0;i<entries.length;i++)for(let j=i+1;j<entries.length;j++)if(overlaps(entries[i],entries[j]))pairs.push([entries[i],entries[j]]); return pairs;
}
function turnaroundWarnings(){
  const warnings=[]; const entries=activeOfficialEntries();
  ['Odd','Even'].forEach(week=>DAYS.forEach(day=>['Lab 1','Lab 2'].forEach(lab=>{
    const list=entries.filter(e=>e.week===week&&e.day===day&&e.lab===lab).sort((a,b)=>minutes(a.start_time)-minutes(b.start_time));
    for(let i=0;i<list.length-1;i++) if(list[i].end_time===list[i+1].start_time){
      warnings.push({week,day,lab,time:list[i].end_time,first:list[i],second:list[i+1]});
    }
  })));
  return warnings;
}

async function init(){
  try{ const response=await fetch('data/bootstrap.json'); APP.bootstrap=await response.json(); }
  catch(err){ document.getElementById('app').innerHTML='<div style="padding:30px">Unable to load app data. Run this folder through a local web server instead of opening index.html directly.</div>'; return; }
  if(APP.role) renderShell(); else renderLogin();
}
function setCrests(){ document.querySelectorAll('[data-school-crest]').forEach(img=>{ img.src=crestUrl(); img.onerror=()=>{ img.onerror=null; img.src='assets/sasj-fallback.svg'; }; }); }
function renderLogin(){
  const tpl=document.getElementById('login-template'); document.getElementById('app').replaceChildren(tpl.content.cloneNode(true)); setCrests();
  document.getElementById('login-button').addEventListener('click',login);
  document.getElementById('login-password').addEventListener('keydown',e=>{if(e.key==='Enter')login();});
}
function login(){
  const role=document.getElementById('login-role').value, password=document.getElementById('login-password').value;
  if(password!=='demo'){ const el=document.getElementById('login-error'); el.textContent='Incorrect prototype password.'; el.hidden=false; return; }
  APP.role=role; sessionStorage.setItem('sasj-role',role); APP.page='dashboard'; renderShell();
}
function signOut(){ sessionStorage.removeItem('sasj-role'); APP.role=null; renderLogin(); }
function renderShell(){
  const tpl=document.getElementById('shell-template'); document.getElementById('app').replaceChildren(tpl.content.cloneNode(true)); setCrests(); renderNav();
  document.getElementById('role-pill').innerHTML=`<span class="role-pill">${esc(ROLE_LABELS[APP.role])}</span>`;
  document.getElementById('sign-out').addEventListener('click',signOut);
  document.getElementById('mobile-menu').addEventListener('click',()=>toggleMobile(true));
  document.getElementById('mobile-backdrop').addEventListener('click',()=>toggleMobile(false));
  document.getElementById('collapse-sidebar').addEventListener('click',()=>document.querySelector('.app-shell').classList.toggle('sidebar-collapsed'));
  navigate(APP.page);
}
function renderNav(){
  const nav=document.getElementById('nav-list');
  nav.innerHTML=NAV.filter(n=>n.roles.includes(APP.role)).map(n=>`<button class="nav-item" data-page="${n.id}"><span class="nav-item__icon">${n.icon}</span><span class="nav-item__label">${n.label}</span></button>`).join('');
  nav.querySelectorAll('[data-page]').forEach(btn=>btn.addEventListener('click',()=>{navigate(btn.dataset.page);toggleMobile(false);}));
}
function toggleMobile(open){ const sb=document.getElementById('sidebar'),bg=document.getElementById('mobile-backdrop'); if(!sb)return; sb.classList.toggle('mobile-open',open); bg.hidden=!open; }
function navigate(page,opts={}){
  const allowed=NAV.find(n=>n.id===page&&n.roles.includes(APP.role)); APP.page=allowed?page:'dashboard';
  if(opts.bookingStatus) APP.bookingStatus={...APP.bookingStatus,...opts.bookingStatus};
  if(opts.scrollBookingStatus) APP.scrollToBookingStatus=true;
  document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===APP.page));
  const [title,sub]=PAGE_META[APP.page]; document.getElementById('page-title').textContent=title; document.getElementById('page-subtitle').textContent=sub;
  const renderers={dashboard:renderDashboard,schedule:renderSchedule,request:renderCreateBooking,inventory:renderInventory,approvals:renderApprovals,timetable:renderTimetable,roster:renderRoster,settings:renderSettings};
  renderers[APP.page]();
}
function toast(message){ const root=document.getElementById('toast-root'); const node=document.createElement('div'); node.className='toast'; node.textContent=message; root.appendChild(node); setTimeout(()=>node.remove(),3400); }

function metricCard(label,value,hint,action='',warning=false){
  return `<button class="card metric ${action?'metric--clickable':''} ${warning?'metric--warning':''}" ${action?`data-dashboard-link="${action}"`:''}><div class="metric__label">${warning?'! ':''}${esc(label)}</div><div class="metric__value">${esc(value)}</div><div class="metric__hint">${hint}</div></button>`;
}
function roleDashboardCopy(){
  if(APP.role==='teacher')return{title:'Quick access',text:'Check lab availability, confirm pre-assigned sessions and create or amend bookings from your phone.'};
  if(APP.role==='labtech')return{title:'Lab operations',text:'Focus on pending requests, preparation turnaround and inventory alerts.'};
  if(APP.role==='hod')return{title:'Science oversight',text:'Review bookings, approvals, timetable setup, roster and inventory.'};
  return{title:'System control',text:'Manage timetable generation, bookings, roster, rules and operational data.'};
}
function labTechOperationalHTML(){const today=isoDate(new Date()),tomorrow=addDaysISO(today,1);const panel=(date,label)=>{const list=activeOfficialEntriesForDate(date).sort((a,b)=>minutes(a.start_time)-minutes(b.start_time));return `<div class="card"><div class="card__header"><div><h2>${label}</h2><p class="small">${formatDateLong(date)}</p></div></div><div class="card__body stack">${list.length?list.map(e=>`<div class="list-item operational-session"><div><strong>${fmtTime(e.start_time)}–${fmtTime(e.end_time)} · ${esc(e.lab)}</strong><p>${esc(e.class_name||e.teacher)} · ${esc(entryStatusText(e))}</p></div><div class="small">${e.activity?esc(e.activity):'Activity not entered'}${e.apparatus?`<br>${esc(e.apparatus)}`:''}</div></div>`).join(''):'<div class="empty-state">No confirmed/reserved lab sessions.</div>'}</div></div>`;};return `<section class="operational-grid">${panel(today,'Today')}${panel(tomorrow,'Tomorrow')}</section>`;}
function renderDashboard(){
  const content=document.getElementById('page-content'); const reqs=requests(); const inv=inventory(); const s=data().baseline_schedule.summary;
  const pending=reqs.filter(r=>r.status==='Pending').length; const invAlerts=inv.filter(i=>i.active!==false&&i.condition!=='Good').length; const gaps=turnaroundWarnings(); const copy=roleDashboardCopy();
  let metrics=[];
  if(APP.role==='teacher'){
    metrics=[metricCard('Pre-assigned sessions / cycle',s.sessions,'18 active mainstream P3–P5 classes'),metricCard('Pending requests',pending,'Requests awaiting approval'),metricCard('Inventory alerts',invAlerts,'Incomplete, low stock or damaged'),metricCard('Active classes',18,'Mainstream P3–P5')];
  }else if(APP.role==='hod'){
    metrics=[metricCard('Pre-assigned sessions / cycle',s.sessions,'Current P3–P5 baseline'),metricCard('Pending requests',pending,'Tap to review all pending requests','pending'),metricCard('Inventory alerts',invAlerts,'Tap to review inventory items needing attention','inventory'),metricCard('Active classes',18,'Mainstream P3–P5')];
  }else if(APP.role==='labtech'){
    const gapHint=gaps.length?gaps.slice(0,3).map(g=>`${g.week} ${g.day} ${fmtTime(g.time)} (${g.lab})`).join('<br>')+(gaps.length>3?`<br>+ ${gaps.length-3} more to review`:''):'Preferred 30-minute turnaround is maintained.';
    metrics=[metricCard('Pending requests',pending,'Tap to review all pending requests','pending'),metricCard('Inventory alerts',invAlerts,'Tap to review inventory items needing attention','inventory'),metricCard('Turnaround gap warnings',gaps.length,gapHint,'',gaps.length>0),metricCard('Official bookings',activeOfficialEntries().length,'Current reserved / confirmed sessions')];
  }else{
    const gapHint=gaps.length?gaps.slice(0,3).map(g=>`${g.week} ${g.day} ${fmtTime(g.time)} (${g.lab})`).join('<br>')+(gaps.length>3?`<br>+ ${gaps.length-3} more to review`:''):'Preferred 30-minute turnaround is maintained.';
    metrics=[metricCard('Pre-assigned sessions / cycle',s.sessions,'Current P3–P5 baseline'),metricCard('Pending requests',pending,'Tap to review all pending requests','pending'),metricCard('Inventory alerts',invAlerts,'Tap to review inventory items needing attention','inventory'),metricCard('Turnaround gap warnings',gaps.length,gapHint,'',gaps.length>0)];
  }
  const showTimetable=['teacher','admin'].includes(APP.role);
  content.innerHTML=`<div class="demo-banner"><strong>Prototype v0.7:</strong> interactive HOD demonstration using the current P3–P5 baseline. Changes are stored only in this browser; production will use shared cloud data and secure authentication.</div><section class="cards">${metrics.join('')}</section><section class="dashboard-grid ${showTimetable?'':'dashboard-grid--single'}"><div class="card"><div class="card__header"><div><h2>${copy.title}</h2><p class="small">${copy.text}</p></div></div><div class="card__body"><div class="quick-actions" id="quick-actions"></div></div></div>${showTimetable?`<div class="card"><div class="card__header"><h2>Current timetable</h2></div><div class="card__body stack"><div><strong>${esc(settings().active_timetable_version)}</strong><div class="small">Current school manual baseline retained while the timetable-version mismatch is being checked.</div></div><div class="info-box"><strong>Timetable Organizer remains a core function.</strong> Future timetable revisions can be uploaded, parsed and re-optimised before publication.</div></div></div>`:''}</section>${APP.role==='labtech'?labTechOperationalHTML():''}`;
  const quick=[['schedule','▦ Lab Schedule'],['request','+ Create Booking'],['inventory','□ Inventory']];
  if(['labtech','admin','hod'].includes(APP.role))quick.push(['approvals','✓ Review Requests']);
  if(['admin','hod'].includes(APP.role))quick.push(['timetable','↻ Timetable Organizer'],['roster','♙ Teacher Deployment']);
  document.getElementById('quick-actions').innerHTML=quick.map(([p,l])=>`<button class="button button--secondary quick-action" data-go="${p}">${l}</button>`).join('');
  document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.go)));
  document.querySelectorAll('[data-dashboard-link="pending"]').forEach(b=>b.addEventListener('click',()=>navigate('schedule',{bookingStatus:{status:'Pending'},scrollBookingStatus:true})));
  document.querySelectorAll('[data-dashboard-link="inventory"]').forEach(b=>b.addEventListener('click',()=>navigate('inventory')));
}

function scheduleLegend(){
  return `<div class="schedule-legend"><span><i class="legend-swatch legend-swatch--confirmed"></i>Confirmed</span><span><i class="legend-swatch legend-swatch--preassigned"></i>Pre-assigned — confirmation required</span><span><i class="legend-swatch legend-swatch--pending"></i>Pending request</span><span><i class="legend-warning">!</i>Pending request overlaps this booking</span></div>`;
}
function renderSchedule(){
  const content=document.getElementById('page-content');
  content.innerHTML=`<div class="page-actions page-actions--equal"><button class="button button--primary" id="schedule-create">+ Create Booking</button><button class="button button--secondary" id="schedule-amend">Amend Booking</button></div><section class="card"><div class="card__body"><div class="section-heading"><h2>Lab timetable</h2><p>Bookings are shown against actual calendar dates. Odd/Even Week is calculated automatically from the active timetable cycle.</p></div><div class="auto-release-note"><strong>Pre-assigned sessions are held only until 2:00 PM on the day before use.</strong> If a teacher has not confirmed by then, the slot is automatically released and becomes available for another booking.</div>${scheduleLegend()}<div class="schedule-date-nav"><button class="button button--ghost" id="schedule-prev-week">‹ Previous Week</button><div class="schedule-week-title"><strong id="schedule-week-range"></strong><span id="schedule-week-parity" class="status status--info"></span></div><button class="button button--ghost" id="schedule-next-week">Next Week ›</button></div><div class="filter-grid schedule-filter-grid"><label class="field"><span>Date</span><input id="schedule-date" type="date" value="${esc(APP.schedule.date)}"></label><label class="field"><span>Lab</span><select id="schedule-lab"><option>Both</option><option>Lab 1</option><option>Lab 2</option></select></label><label class="field"><span>Class</span><select id="schedule-class"><option>All</option>${data().classes.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><div class="field"><span>View</span><div class="segmented segmented--full"><button id="view-day">Day</button><button id="view-week">Week</button></div></div></div><div id="released-slot-summary"></div><div id="schedule-content"></div></div></section><section class="card schedule-help"><div class="card__header"><h2>Using the lab schedule</h2></div><div class="card__body help-grid"><div><strong>1. Confirm your pre-assigned session</strong><p>Click the <strong>blue</strong> pre-assigned session. Confirm it by <strong>2:00 PM on the day before</strong>, then enter the activity number, number of sets and any special requests or assistance needed. Once confirmed, the booking turns <strong>green</strong>.</p></div><div><strong>2. Automatic release</strong><p>If a pre-assigned session is still unconfirmed after 2:00 PM on the previous day, the app releases it automatically. This rule applies only to pre-assigned sessions; approved ad hoc and special-event bookings remain confirmed.</p></div><div><strong>3. Create or amend a booking</strong><p>Use <strong>Create Booking</strong> for a new session. Use <strong>Amend Booking</strong> or click an existing booking to request a new date/time. Teacher scheduling changes require approval; HOD/SH, Lab Technician and System Admin can change them directly when no conflict exists.</p></div></div></section><section class="card" id="booking-status-section"><div class="card__header"><div><h2>Booking Status</h2><p class="small">Search pre-assigned sessions, confirmed bookings and requests. Dates shown below correspond to actual calendar dates.</p></div></div><div class="card__body"><div class="filter-grid booking-status-filters"><label class="field"><span>Search</span><input id="status-search" placeholder="Class, teacher, activity or event..." value="${esc(APP.bookingStatus.search)}"></label><label class="field"><span>Status</span><select id="status-filter"><option>All</option><option>Pre-assigned</option><option>Confirmed</option><option>Pending</option><option>Approved</option><option>Rejected</option><option>Cancelled</option><option>Released</option></select></label></div><div id="status-results"></div></div></section>`;
  const de=document.getElementById('schedule-date'),le=document.getElementById('schedule-lab'),ce=document.getElementById('schedule-class');
  le.value=APP.schedule.lab; ce.value=APP.schedule.classFilter;
  de.addEventListener('change',()=>{APP.schedule.date=de.value;drawSchedule();drawBookingStatus();});
  le.addEventListener('change',()=>{APP.schedule.lab=le.value;drawSchedule();}); ce.addEventListener('change',()=>{APP.schedule.classFilter=ce.value;drawSchedule();});
  document.getElementById('view-day').addEventListener('click',()=>{APP.schedule.view='day';drawSchedule();}); document.getElementById('view-week').addEventListener('click',()=>{APP.schedule.view='week';drawSchedule();});
  document.getElementById('schedule-prev-week').addEventListener('click',()=>{APP.schedule.date=addDaysISO(APP.schedule.date,-7);de.value=APP.schedule.date;drawSchedule();drawBookingStatus();});
  document.getElementById('schedule-next-week').addEventListener('click',()=>{APP.schedule.date=addDaysISO(APP.schedule.date,7);de.value=APP.schedule.date;drawSchedule();drawBookingStatus();});
  document.getElementById('schedule-create').addEventListener('click',()=>navigate('request')); document.getElementById('schedule-amend').addEventListener('click',openAmendSearchModal);
  const ss=document.getElementById('status-search'),sf=document.getElementById('status-filter');sf.value=APP.bookingStatus.status;ss.addEventListener('input',()=>{APP.bookingStatus.search=ss.value;drawBookingStatus();});sf.addEventListener('change',()=>{APP.bookingStatus.status=sf.value;drawBookingStatus();});
  drawSchedule();drawBookingStatus();if(APP.scrollToBookingStatus){APP.scrollToBookingStatus=false;setTimeout(()=>document.getElementById('booking-status-section')?.scrollIntoView({behavior:'smooth',block:'start'}),120);}
}
function entryMatchesFilters(e){ return (APP.schedule.lab==='Both'||e.lab===APP.schedule.lab)&&(APP.schedule.classFilter==='All'||e.class_name===APP.schedule.classFilter); }
function scheduleEntriesForDate(date,lab){ return [...activeOfficialEntriesForDate(date),...pendingRequestEntriesForDate(date)].filter(e=>e.lab===lab&&entryMatchesFilters(e)); }
function drawSchedule(){
  drawReleasedSlotSummary();
  const target=document.getElementById('schedule-content');if(!target)return;document.getElementById('view-day').classList.toggle('active',APP.schedule.view==='day');document.getElementById('view-week').classList.toggle('active',APP.schedule.view==='week');
  const mon=mondayISO(APP.schedule.date);document.getElementById('schedule-week-range').textContent=weekRangeLabel(mon);document.getElementById('schedule-week-parity').textContent=`${weekParityFromDate(mon)} Week`;
  if(APP.schedule.view==='week')drawWeek(target,mon);else{const labs=APP.schedule.lab==='Both'?['Lab 1','Lab 2']:[APP.schedule.lab];target.innerHTML=`<div class="schedule-day-heading"><strong>${formatDateLong(APP.schedule.date)}</strong><span class="status status--info">${weekParityFromDate(APP.schedule.date)} Week</span></div><div class="schedule-wrap"><div class="day-schedule">${labs.map(l=>timelineHTML(l,APP.schedule.date)).join('')}</div></div>`;} bindScheduleEntryClicks(target);
}
function drawReleasedSlotSummary(){const box=document.getElementById('released-slot-summary');if(!box)return;const mon=mondayISO(APP.schedule.date),released=[];for(let i=0;i<5;i++){const date=addDaysISO(mon,i);baselineOccurrencesForDate(date,true).filter(e=>e.status==='Released').forEach(e=>released.push(e));}box.innerHTML=released.length?`<div class="released-slot-box"><strong>Available — released pre-assigned slots</strong><div class="tag-list">${released.map(e=>`<span class="tag tag--available">${formatDateShort(e.date)} · ${e.lab} · ${fmtTime(e.start_time)}–${fmtTime(e.end_time)} · ${esc(e.class_name)}</span>`).join('')}</div></div>`:'';}
function bookingBarClass(entry){ if(entry.status==='Pending')return'booking-bar--pending';if(entry.source_kind==='baseline'&&entry.status==='Pre-assigned')return'booking-bar--preassigned';return'booking-bar--confirmed'; }
function entryStatusText(entry){ if(entry.source_kind==='request')return displayRequestStatus(entry);return entry.status; }
function entryTypeText(entry){ if(entry.source_kind==='baseline')return'Pre-assigned';return requestTypeLabel(entry.request_type); }
function timelineHTML(lab,date){
  const entries=scheduleEntriesForDate(date,lab).sort((a,b)=>minutes(a.start_time)-minutes(b.start_time)),start=7*60+30,px=40/30;let labels='';for(let t=start;t<=14*60;t+=60){const v=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;labels+=`<span class="timeline-label" style="top:${(t-start)*px}px">${fmtTime(v)}</span>`;}const bars=entries.map(e=>{const top=(minutes(e.start_time)-start)*px,height=Math.max(36,(minutes(e.end_time)-minutes(e.start_time))*px-4),warnings=e.status==='Pending'?[]:pendingWarningsForEntry(e),pending=e.status==='Pending',offset=pending?'left:20%;right:8px;':'left:8px;right:8px;';return`<button class="booking-bar ${bookingBarClass(e)} ${e.is_preferred_lab===false?'cross-lab':''}" style="top:${top}px;height:${height}px;${offset}" data-entry-kind="${e.source_kind}" data-entry-id="${encodeURIComponent(e.source_id)}">${warnings.length?`<span class="booking-conflict-badge" title="Pending request overlaps this booking">!</span>`:''}<div class="booking-bar__title">${esc(e.class_name||e.teacher)}</div><div class="booking-bar__meta">${fmtTime(e.start_time)}–${fmtTime(e.end_time)} · ${esc(entryTypeText(e))} · ${esc(entryStatusText(e))}</div></button>`;}).join('');return`<div class="card lab-timeline"><div class="lab-timeline__header"><strong>${lab}</strong><span class="status status--preassigned">${lab==='Lab 1'?'P3/P4 preferred':'P5/P6 preferred'}</span></div><div class="timeline-body"><div class="timeline-labels">${labels}</div>${bars}</div></div>`;
}
function drawWeek(target,monday){
  const labs=APP.schedule.lab==='Both'?['Lab 1','Lab 2']:[APP.schedule.lab];let html='<div class="week-view-scroll"><div class="week-grid"><div class="week-cell week-header"></div>'+DAYS.map((d,i)=>`<div class="week-cell week-header"><strong>${d}</strong><span>${formatDateShort(addDaysISO(monday,i))}</span></div>`).join('');
  labs.forEach(lab=>{html+=`<div class="week-cell week-lab-label">${lab}</div>`;DAYS.forEach((day,i)=>{const date=addDaysISO(monday,i),entries=scheduleEntriesForDate(date,lab).sort((a,b)=>minutes(a.start_time)-minutes(b.start_time));html+=`<div class="week-cell">${entries.length?entries.map(e=>{const warnings=e.status==='Pending'?[]:pendingWarningsForEntry(e);return`<button class="week-booking ${bookingBarClass(e)}" data-entry-kind="${e.source_kind}" data-entry-id="${encodeURIComponent(e.source_id)}">${warnings.length?'<span class="week-warning">!</span>':''}<strong>${esc(e.class_name||e.teacher)}</strong>${fmtTime(e.start_time)}–${fmtTime(e.end_time)}<br><span>${esc(entryTypeText(e))} · ${esc(entryStatusText(e))}</span></button>`;}).join(''):'<span class="small">Available</span>'}</div>`;});});html+='</div></div>';target.innerHTML=html;
}
function bindScheduleEntryClicks(root){ root.querySelectorAll('[data-entry-kind]').forEach(el=>el.addEventListener('click',()=>openEntryDetail(el.dataset.entryKind,decodeURIComponent(el.dataset.entryId)))); }
function getEntry(kind,id){
  if(kind==='baseline'){const parts=id.split('@@'),date=parts.pop(),allocKey=parts.join('@@');const a=data().baseline_schedule.allocations.find(x=>allocationKey(x)===allocKey);return a?baselineOccurrence(a,date):null;}const r=requests().find(x=>x.id===id);return r?requestEntry(r):null;
}

function openEntryDetail(kind,id){
  const entry=getEntry(kind,id); if(!entry)return;
  if(kind==='request' && (entry.status==='Pending'||entry.request_type==='amendment'||['Rejected','Cancelled'].includes(entry.status))) return openRequestDetail(entry.id);
  openOfficialBookingDetail(entry);
}
function teacherSelectOptions(selected='',className=''){ let linked=className?teachers().filter(t=>(t.classes||[]).includes(className)&&t.active!==false):teachers().filter(t=>t.active!==false); if(!linked.length) linked=teachers().filter(t=>t.active!==false); return linked.map(t=>`<option value="${esc(t.name)}" ${t.name===selected?'selected':''}>${esc(t.name)}</option>`).join(''); }
function classOptions(selected='',allowEvent=true){ return `${allowEvent?'<option value="">Event / no class</option>':''}${data().classes.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('')}`; }
function scheduleEditorHTML(entry,disabled=false){ return `<div class="form-grid scheduling-fields"><label class="field"><span>Date</span><input id="edit-date" type="date" ${disabled?'disabled':''} value="${esc(entry.date||APP.schedule.date)}"></label><label class="field"><span>Lab</span><select id="edit-lab" ${disabled?'disabled':''}><option>Lab 1</option><option>Lab 2</option></select></label><label class="field"><span>Time</span><select id="edit-start" ${disabled?'disabled':''}>${timeOptions(entry.start_time)}</select></label></div>`; }
function setScheduleEditorValues(entry){ const l=document.getElementById('edit-lab');if(l)l.value=entry.lab; }
function detailFieldsHTML(entry){ return `<label class="field"><span>Activity</span><input id="edit-activity" value="${esc(entry.activity||'')}" placeholder="e.g. 1.3"></label><label class="field"><span>Number of sets</span><input id="edit-sets" inputmode="numeric" value="${esc(entry.sets||'')}" placeholder="e.g. 10"></label><label class="field span-2"><span>Special request / apparatus / assistance needed</span><textarea id="edit-apparatus" placeholder="Apparatus, quantities, setup notes, assistance needed...">${esc(entry.apparatus||'')}</textarea></label><label class="field span-2"><span>Remarks</span><textarea id="edit-remarks" placeholder="Optional remarks">${esc(entry.remarks||'')}</textarea></label>`; }
function openOfficialBookingDetail(entry){
  const privileged=roleCanDirectBook(),isBaseline=entry.source_kind==='baseline',isUnconfirmed=isBaseline&&entry.status==='Pre-assigned',selectedTeacher=entry.teacher?.split(' / ')[0]||teacherNamesForClass(entry.class_name)[0]||'';
  modal('Lab session details',`<div class="stack"><div class="booking-detail-summary"><div><h3>${esc(entry.class_name||entry.teacher)}</h3><p>${esc(entryTypeText(entry))} · ${entry.date?formatDateLong(entry.date):`${entry.week} ${entry.day}`} · ${entry.lab} · ${fmtTime(entry.start_time)}–${fmtTime(entry.end_time)}</p></div><span class="status status--${statusClass(entryStatusText(entry))}">${esc(entryStatusText(entry))}</span></div>${isUnconfirmed?`<div class="warning-box"><strong>Confirmation required:</strong> confirm this pre-assigned session by <strong>${fmtTime(settings().confirmation_deadline)} on ${formatDateLong(addDaysISO(entry.date,-1))}</strong>. If it remains unconfirmed after the deadline, it will be released automatically.</div>`:''}<label class="field"><span>Teacher / requester</span><select id="edit-teacher">${teacherSelectOptions(selectedTeacher,entry.class_name)}</select></label>${privileged?scheduleEditorHTML(entry,false):`<div class="info-box"><strong>Schedule:</strong> ${formatDateLong(entry.date)} · ${entry.lab} · ${fmtTime(entry.start_time)}–${fmtTime(entry.end_time)}. Use <strong>Amend Date/Time</strong> below if you need to change it.</div>`}<div class="form-grid">${detailFieldsHTML(entry)}</div><div id="direct-edit-conflict"></div></div>`,`<button class="button button--danger" id="detail-cancel">Cancel Booking</button>${!privileged?'<button class="button button--secondary" id="detail-amend">Amend Date/Time</button>':''}<button class="button button--primary" id="detail-save">Save Details</button>${isUnconfirmed?'<button class="button button--success" id="detail-confirm">Confirm Session</button>':''}`);
  if(privileged){setScheduleEditorValues(entry);['edit-date','edit-lab','edit-start'].forEach(id=>document.getElementById(id)?.addEventListener('change',()=>showDirectConflict(entry)));showDirectConflict(entry);}document.getElementById('detail-save').addEventListener('click',()=>saveOfficialEntry(entry,false));document.getElementById('detail-confirm')?.addEventListener('click',()=>saveOfficialEntry(entry,true));document.getElementById('detail-amend')?.addEventListener('click',()=>{closeModal();openAmendForm(entry);});document.getElementById('detail-cancel').addEventListener('click',()=>openDeleteConfirmation(entry));
}
function editedCandidate(entry){ const start=document.getElementById('edit-start')?.value||entry.start_time,date=document.getElementById('edit-date')?.value||entry.date; return {...entry,date,week:weekParityFromDate(date),day:dayCodeFromDate(date),lab:document.getElementById('edit-lab')?.value||entry.lab,start_time:start,end_time:endAfterHour(start)}; }
function showDirectConflict(entry){ const box=document.getElementById('direct-edit-conflict');if(!box)return;const candidate=editedCandidate(entry);const c=findOfficialConflicts(candidate,entryRef(entry));box.innerHTML=c.length?conflictBoxHTML(c,'This change cannot be saved until the conflict is resolved.'):'<div class="info-box"><strong>No scheduling conflict.</strong> This change can be saved directly.</div>'; }
function readDetailValues(){ return {teacher:document.getElementById('edit-teacher')?.value||'',activity:activityLabel(document.getElementById('edit-activity')?.value||''),sets:document.getElementById('edit-sets')?.value||'',apparatus:document.getElementById('edit-apparatus')?.value.trim()||'',remarks:document.getElementById('edit-remarks')?.value.trim()||''}; }
function saveOfficialEntry(entry,confirmSession=false){
  const vals=readDetailValues();let candidate={...entry,...vals};if(roleCanDirectBook()){candidate=editedCandidate(candidate);const conflicts=findOfficialConflicts(candidate,entryRef(entry));if(conflicts.length){toast('Cannot save: this change creates a scheduling conflict.');showDirectConflict(entry);return;}}
  if(entry.source_kind==='baseline'){
    const actions=sessionActions(),key=entry.source_id,existing=actions[key]||{};actions[key]={...existing,...vals,allocation_key:entry.original_key,original_date:entry.original_date||entry.date,date:candidate.date||entry.date,lab:candidate.lab,start_time:candidate.start_time,end_time:candidate.end_time,status:confirmSession?'Confirmed':(existing.status||entry.status),updated_at:new Date().toLocaleString('en-SG')};writeLocal('sasj-v07-session-actions',actions);
  }else{const arr=requests(),r=arr.find(x=>x.id===entry.source_id);if(!r)return;Object.assign(r,vals);if(roleCanDirectBook())Object.assign(r,{date:candidate.date,week:weekParityFromDate(candidate.date),day:dayCodeFromDate(candidate.date),lab:candidate.lab,start_time:candidate.start_time,end_time:candidate.end_time});writeLocal('sasj-v07-requests',arr);}
  closeModal();toast(confirmSession?'Session confirmed.':'Booking details updated.');if(APP.page==='schedule'){drawSchedule();drawBookingStatus();}
}
function openAmendForm(entry){
  const selectedTeacher=entry.teacher?.split(' / ')[0]||teacherNamesForClass(entry.class_name)[0]||'';
  modal('Amend booking date / time',`<div class="stack"><div class="info-box"><strong>Current booking:</strong> ${esc(entry.class_name||entry.teacher)} · ${formatDateLong(entry.date)} · ${entry.lab} · ${fmtTime(entry.start_time)}–${fmtTime(entry.end_time)}</div><label class="field"><span>Your name</span><select id="amend-teacher">${teacherSelectOptions(selectedTeacher,entry.class_name)}</select></label><div class="form-grid"><label class="field"><span>New date</span><input id="amend-date" type="date" value="${esc(entry.date)}"></label><label class="field"><span>New lab</span><select id="amend-lab"><option>Lab 1</option><option>Lab 2</option></select></label><label class="field"><span>New time</span><select id="amend-start">${timeOptions(entry.start_time)}</select></label><label class="field span-2"><span>Reason for amendment</span><textarea id="amend-reason" placeholder="Why is this change needed?"></textarea></label></div><div id="amend-conflict"></div></div>`,`<button class="button button--ghost" data-close-modal>Cancel</button><button class="button button--primary" id="submit-amendment">Submit Amendment</button>`);
  document.getElementById('amend-lab').value=entry.lab;const check=()=>{const start=document.getElementById('amend-start').value,date=document.getElementById('amend-date').value,candidate={...entry,request_type:'amendment',date,week:weekParityFromDate(date),day:dayCodeFromDate(date),lab:document.getElementById('amend-lab').value,start_time:start,end_time:endAfterHour(start),original_kind:entry.source_kind,original_id:entry.source_id};const conflicts=findOfficialConflicts(candidate);document.getElementById('amend-conflict').innerHTML=conflicts.length?conflictBoxHTML(conflicts,'You may still submit the amendment. It cannot be approved until the conflict is resolved.'):'<div class="info-box"><strong>No conflict detected.</strong> The amendment will still require approval.</div>';};['amend-date','amend-lab','amend-start'].forEach(id=>document.getElementById(id).addEventListener('change',check));check();
  document.getElementById('submit-amendment').addEventListener('click',()=>{const start=document.getElementById('amend-start').value,date=document.getElementById('amend-date').value;const r={id:uid('req'),request_type:'amendment',teacher:document.getElementById('amend-teacher').value,class_name:entry.class_name||'Event / no class',date,week:weekParityFromDate(date),day:dayCodeFromDate(date),lab:document.getElementById('amend-lab').value,start_time:start,end_time:endAfterHour(start),activity:entry.activity||'',sets:entry.sets||'',apparatus:entry.apparatus||'',remarks:document.getElementById('amend-reason').value.trim(),status:'Pending',original_kind:entry.source_kind,original_id:entry.source_id,original_summary:`${formatDateLong(entry.date)} ${entry.lab} ${entry.start_time}`,submitted_at:new Date().toLocaleString('en-SG')};const arr=requests();arr.unshift(r);writeLocal('sasj-v07-requests',arr);closeModal();toast('Amendment submitted for approval.');if(APP.page==='schedule'){drawSchedule();drawBookingStatus();}});
}
function openDeleteConfirmation(entry){
  modal('Cancel booking',`<div class="stack"><div class="warning-box"><strong>This takes effect immediately.</strong> The slot will be freed as soon as you confirm cancellation.</div><p>To prevent accidental cancellation, type <strong>delete</strong> below.</p><label class="field"><span>Type “delete” to confirm</span><input id="delete-confirm-text" autocomplete="off" placeholder="delete"></label></div>`,`<button class="button button--ghost" data-close-modal>Keep Booking</button><button class="button button--danger" id="delete-confirm-button">Cancel Booking</button>`);
  const input=document.getElementById('delete-confirm-text'),btn=document.getElementById('delete-confirm-button'); btn.disabled=true; input.addEventListener('input',()=>btn.disabled=input.value.trim().toLowerCase()!=='delete'); btn.addEventListener('click',()=>cancelEntry(entry));
}
function cancelEntry(entry){
  if(entry.source_kind==='baseline'){const actions=sessionActions(),existing=actions[entry.source_id]||{};actions[entry.source_id]={...existing,allocation_key:entry.original_key,original_date:entry.original_date||entry.date,date:entry.date,status:'Cancelled',cancelled_at:new Date().toLocaleString('en-SG'),cancelled_by:ROLE_LABELS[APP.role]};writeLocal('sasj-v07-session-actions',actions);}else{const arr=requests(),r=arr.find(x=>x.id===entry.source_id);if(r){r.status='Cancelled';r.cancelled_at=new Date().toLocaleString('en-SG');r.cancelled_by=ROLE_LABELS[APP.role];writeLocal('sasj-v07-requests',arr);}}
  recordAudit('Booking cancelled',`${entry.class_name||entry.teacher} · ${entry.lab} · ${entry.date}`);closeModal();toast('Booking cancelled and slot released.');if(APP.page==='schedule'){drawSchedule();drawBookingStatus();}if(APP.page==='approvals')drawApprovals();
}
function openAmendSearchModal(){
  modal('Amend Booking',`<div class="stack"><div class="filter-grid amend-search-grid"><label class="field"><span>Teacher</span><select id="amend-search-teacher"><option value="">Any teacher</option>${teacherSelectOptions()}</select></label><label class="field"><span>Class</span><select id="amend-search-class"><option value="">Any class</option>${data().classes.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><button class="button button--primary button--wide" id="amend-search-button">Search</button><div id="amend-search-results" class="list"></div></div>`);
  document.getElementById('amend-search-button').addEventListener('click',()=>{const teacher=document.getElementById('amend-search-teacher').value,cls=document.getElementById('amend-search-class').value;if(!teacher&&!cls){toast('Select a teacher or class first.');return;}let entries=activeOfficialEntriesInWindow(APP.schedule.date,6);if(cls)entries=entries.filter(e=>e.class_name===cls);if(teacher){const linked=new Set(teachers().find(t=>t.name===teacher)?.classes||[]);entries=entries.filter(e=>e.teacher===teacher||linked.has(e.class_name));}entries.sort((a,b)=>`${a.date}${a.start_time}`.localeCompare(`${b.date}${b.start_time}`));const result=document.getElementById('amend-search-results');result.innerHTML=entries.length?entries.map(e=>`<button class="list-item amend-result" data-kind="${e.source_kind}" data-id="${encodeURIComponent(e.source_id)}"><strong>${esc(e.class_name||e.teacher)}</strong><span>${formatDateLong(e.date)} · ${e.lab} · ${fmtTime(e.start_time)}–${fmtTime(e.end_time)} · ${esc(entryStatusText(e))}</span></button>`).join(''):'<div class="empty-state">No matching active booking found.</div>';result.querySelectorAll('[data-kind]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.kind,id=decodeURIComponent(b.dataset.id);closeModal();openEntryDetail(kind,id);}));});
}

function bookingStatusRecords(){
  const base=baselineOccurrencesForWeek(APP.schedule.date,true).map(e=>({...e,ui_status:e.status,ui_type:'Pre-assigned'}));
  const req=requests().map(r=>({...requestEntry(r),ui_status:displayRequestStatus(r),ui_type:requestTypeLabel(r.request_type)}));
  return [...base,...req].sort((a,b)=>`${a.date||''}${a.start_time||''}`.localeCompare(`${b.date||''}${b.start_time||''}`));
}
function drawBookingStatus(){
  const target=document.getElementById('status-results');if(!target)return;const q=APP.bookingStatus.search.toLowerCase().trim(),status=APP.bookingStatus.status; let arr=bookingStatusRecords();
  if(q)arr=arr.filter(e=>JSON.stringify([e.class_name,e.teacher,e.activity,e.remarks,e.apparatus,e.booking_type,e.request_type]).toLowerCase().includes(q)); if(status!=='All')arr=arr.filter(e=>e.ui_status===status);
  target.innerHTML=arr.length?`<div class="list booking-status-list">${arr.map(bookingStatusCard).join('')}</div>`:'<div class="empty-state">No booking matches your search.</div>';
  target.querySelectorAll('[data-status-kind]').forEach(b=>b.addEventListener('click',()=>openEntryDetail(b.dataset.statusKind,decodeURIComponent(b.dataset.statusId))));
}
function bookingStatusCard(e){
  const pendingConf=e.status==='Pending'?conflictsForPending(e):[],officialWarnings=e.status==='Pending'?[]:(!['Cancelled','Rejected','Released'].includes(e.ui_status)?pendingWarningsForEntry(e):[]);
  return `<button class="list-item booking-status-card" data-status-kind="${e.source_kind}" data-status-id="${encodeURIComponent(e.source_id)}"><div class="list-item__top"><div><h3>${esc(e.class_name||e.teacher)}</h3><p>${esc(e.teacher||teacherNamesForClass(e.class_name).join(' / ')||'Science Teacher')} · ${e.date?formatDateLong(e.date):`${e.week} ${e.day}`} · ${e.lab} · ${fmtTime(e.start_time)}–${fmtTime(e.end_time)}</p>${e.activity?`<p><strong>${esc(e.activity)}</strong>${e.apparatus?' · '+esc(e.apparatus):''}</p>`:''}<p>${esc(e.ui_type)}</p></div><span class="status status--${statusClass(e.ui_status)}">${esc(e.ui_status)}</span></div>${pendingConf.length?`<div class="conflict-box compact"><strong>! ${pendingConf.length} scheduling conflict${pendingConf.length===1?'':'s'} — approval is blocked until resolved.</strong></div>`:''}${officialWarnings.length?`<div class="warning-box compact"><strong>! ${officialWarnings.length} pending request${officialWarnings.length===1?'':'s'} overlap this booking.</strong></div>`:''}</button>`;
}
function openRequestDetail(id){
  const arr=requests(),r=arr.find(x=>x.id===id);if(!r)return;const display=displayRequestStatus(r),editable=r.status==='Pending',privileged=roleCanApprove(),conflicts=r.status==='Pending'?conflictsForPending(r):[],d=requestDate(r);
  modal(`${requestTypeLabel(r.request_type)} details`,`<div class="stack"><div class="booking-detail-summary"><div><h3>${esc(r.class_name||r.teacher)}</h3><p>${formatDateLong(d)} · ${r.lab} · ${fmtTime(r.start_time)}–${fmtTime(r.end_time)}</p></div><span class="status status--${statusClass(display)}">${esc(display)}</span></div>${r.request_type==='amendment'&&r.original_summary?`<div class="info-box"><strong>Original booking:</strong> ${esc(r.original_summary)}</div>`:''}<label class="field"><span>Teacher / requester</span><select id="pending-teacher" ${editable?'':'disabled'}>${teacherSelectOptions(r.teacher,r.class_name)}</select></label><div class="form-grid"><label class="field"><span>Date</span><input id="pending-date" type="date" ${editable?'':'disabled'} value="${esc(d)}"></label><label class="field"><span>Lab</span><select id="pending-lab" ${editable?'':'disabled'}><option>Lab 1</option><option>Lab 2</option></select></label><label class="field"><span>Time</span><select id="pending-start" ${editable?'':'disabled'}>${timeOptions(r.start_time)}</select></label><label class="field"><span>Activity</span><input id="pending-activity" ${editable?'':'disabled'} value="${esc(r.activity||'')}"></label><label class="field"><span>Number of sets</span><input id="pending-sets" ${editable?'':'disabled'} value="${esc(r.sets||'')}"></label><label class="field span-2"><span>Special request / apparatus / assistance needed</span><textarea id="pending-apparatus" ${editable?'':'disabled'}>${esc(r.apparatus||'')}</textarea></label><label class="field span-2"><span>Remarks / reason</span><textarea id="pending-remarks" ${editable?'':'disabled'}>${esc(r.remarks||'')}</textarea></label></div><div id="pending-conflict-box">${conflicts.length?conflictBoxHTML(conflicts,'This request cannot be approved until the conflict is resolved.'):'<div class="info-box"><strong>No current scheduling conflict.</strong></div>'}</div></div>`,`${editable?'<button class="button button--danger" id="pending-cancel">Cancel Request</button><button class="button button--primary" id="pending-save">Update Request</button>':''}${editable&&privileged?'<button class="button button--danger" id="pending-reject">Reject</button><button class="button button--success" id="pending-approve">Approve</button>':''}`);
  document.getElementById('pending-lab').value=r.lab;
  if(editable){const refresh=()=>{syncPendingFormToTemp(r);const c=conflictsForPending(r);document.getElementById('pending-conflict-box').innerHTML=c.length?conflictBoxHTML(c,'This request cannot be approved until the conflict is resolved.'):'<div class="info-box"><strong>No current scheduling conflict.</strong></div>';};['pending-date','pending-lab','pending-start'].forEach(x=>document.getElementById(x).addEventListener('change',refresh));document.getElementById('pending-save').addEventListener('click',()=>{syncPendingFormToTemp(r);writeLocal('sasj-v07-requests',arr);closeModal();toast('Pending request updated.');if(APP.page==='schedule'){drawSchedule();drawBookingStatus();}});document.getElementById('pending-cancel').addEventListener('click',()=>openDeleteConfirmation(requestEntry(r)));document.getElementById('pending-reject')?.addEventListener('click',()=>{closeModal();updateRequestStatus(r.id,'Rejected');});document.getElementById('pending-approve')?.addEventListener('click',()=>{closeModal();updateRequestStatus(r.id,'Approved');});}
}
function syncPendingFormToTemp(r){const start=document.getElementById('pending-start').value,date=document.getElementById('pending-date').value;Object.assign(r,{teacher:document.getElementById('pending-teacher').value,date,week:weekParityFromDate(date),day:dayCodeFromDate(date),lab:document.getElementById('pending-lab').value,start_time:start,end_time:endAfterHour(start),activity:activityLabel(document.getElementById('pending-activity').value),sets:document.getElementById('pending-sets').value,apparatus:document.getElementById('pending-apparatus').value.trim(),remarks:document.getElementById('pending-remarks').value.trim()});}
function conflictBoxHTML(conflicts,message){return `<div class="conflict-box"><strong>! Conflict detected</strong><p>${esc(message)}</p>${conflicts.map(c=>`<div class="conflict-line"><strong>${esc(c.class_name||c.teacher)}</strong><span>${esc(teacherNamesForClass(c.class_name).join(' / ')||c.teacher||'Teacher not linked')} · ${c.date?formatDateLong(c.date):`${c.week} ${c.day}`} · ${c.lab} · ${fmtTime(c.start_time)}–${fmtTime(c.end_time)}</span></div>`).join('')}</div>`;}
function renderCreateBooking(){
  const content=document.getElementById('page-content');content.innerHTML=`<section class="card"><div class="card__header"><div><h2>Create Booking</h2><p class="small">Science Teachers submit a request for approval. HOD/SH, Lab Technician and System Admin can create a booking directly, but the app blocks any confirmed booking that conflicts with an existing one.</p></div></div><div class="card__body"><div class="form-grid create-booking-grid"><label class="field"><span>Booking type</span><select id="req-type"><option value="additional">Ad hoc / additional lab session</option><option value="event">Special event / workshop / PSLE use</option></select></label><label class="field"><span>Your name / requester</span><select id="req-teacher"><option value="">Select name</option>${teacherSelectOptions()}</select></label><label class="field"><span>Class</span><select id="req-class">${classOptions('',true)}</select></label><label class="field"><span>Date</span><input id="req-date" type="date" value="${esc(APP.schedule.date)}"></label><label class="field"><span>Lab</span><select id="req-lab"><option>Lab 1</option><option>Lab 2</option></select></label><label class="field"><span>Time</span><select id="req-start">${timeOptions('09:30')}</select></label><label class="field"><span>Activity</span><input id="req-activity" placeholder="e.g. 5.6"></label><label class="field"><span>Number of sets</span><input id="req-sets" inputmode="numeric" placeholder="e.g. 10"></label><label class="field span-2"><span>Special request / apparatus / assistance needed</span><textarea id="req-apparatus" placeholder="Apparatus, quantities, setup or assistance required..."></textarea></label><label class="field span-2"><span>Remarks / purpose</span><textarea id="req-remarks" placeholder="Optional reason or event details"></textarea></label></div><div id="request-conflict" style="margin-top:14px"></div><div class="page-actions page-actions--equal" style="margin-top:14px"><button class="button button--primary" id="submit-request">${roleCanDirectBook()?'Create Confirmed Booking':'Submit Request'}</button><button class="button button--ghost" id="back-schedule">Back to Schedule</button></div></div></section>`;
  const typeEl=document.getElementById('req-type'),classEl=document.getElementById('req-class');const updateType=()=>{if(typeEl.value==='event')classEl.value='';};typeEl.addEventListener('change',()=>{updateType();checkCreateConflict();});['req-date','req-lab','req-start'].forEach(id=>document.getElementById(id).addEventListener('change',checkCreateConflict));checkCreateConflict();document.getElementById('submit-request').addEventListener('click',submitCreateBooking);document.getElementById('back-schedule').addEventListener('click',()=>navigate('schedule'));
}
function createCandidateFromForm(){const start=document.getElementById('req-start').value,date=document.getElementById('req-date').value;return{request_type:document.getElementById('req-type').value,teacher:document.getElementById('req-teacher').value,class_name:document.getElementById('req-class').value||'Event / no class',date,week:weekParityFromDate(date),day:dayCodeFromDate(date),lab:document.getElementById('req-lab').value,start_time:start,end_time:endAfterHour(start)};}
function checkCreateConflict(){ const target=document.getElementById('request-conflict');if(!target)return;const conflicts=findOfficialConflicts(createCandidateFromForm());target.innerHTML=conflicts.length?conflictBoxHTML(conflicts,roleCanDirectBook()?'Direct booking is blocked until the conflicting slot is changed or cancelled.':'You may still submit the request. The Lab Technician/HOD/Admin must resolve the conflict before it can be approved.'):'<div class="info-box"><strong>No scheduling conflict detected.</strong></div>'; }
function submitCreateBooking(){
  const c=createCandidateFromForm(); if(!c.teacher){toast('Select your name / requester.');return;} if(c.request_type!=='event'&&(!c.class_name||c.class_name==='Event / no class')){toast('Select a class.');return;} const conflicts=findOfficialConflicts(c); if(roleCanDirectBook()&&conflicts.length){toast('Cannot create booking: resolve the scheduling conflict first.');checkCreateConflict();return;}
  const r={id:uid('req'),...c,activity:activityLabel(document.getElementById('req-activity').value),sets:document.getElementById('req-sets').value,apparatus:document.getElementById('req-apparatus').value.trim(),remarks:document.getElementById('req-remarks').value.trim(),status:roleCanDirectBook()?'Approved':'Pending',submitted_at:new Date().toLocaleString('en-SG')}; const arr=requests();arr.unshift(r);writeLocal('sasj-v07-requests',arr);toast(r.status==='Approved'?'Confirmed booking created.':'Booking request submitted for approval.');navigate('schedule',{bookingStatus:{status:r.status==='Approved'?'Confirmed':'Pending'},scrollBookingStatus:true});
}

function renderApprovals(){ const content=document.getElementById('page-content'); content.innerHTML=`<section class="card"><div class="card__header"><div><h2>Pending requests</h2><p class="small">HOD/SH, Lab Technician and System Admin can approve any request. A request may be submitted against an occupied slot, but approval is blocked until all conflicts have been resolved.</p></div></div><div class="card__body"><div id="approval-list"></div></div></section>`; drawApprovals(); }
function drawApprovals(){const arr=requests().filter(r=>r.status==='Pending'),target=document.getElementById('approval-list');target.innerHTML=arr.length?`<div class="list">${arr.map(r=>{const c=conflictsForPending(r),d=requestDate(r);return`<article class="list-item"><div class="list-item__top"><div><h3>${esc(r.class_name)} · ${esc(r.teacher)}</h3><p>${formatDateLong(d)} · ${r.lab} · ${fmtTime(r.start_time)}–${fmtTime(r.end_time)} · ${esc(requestTypeLabel(r.request_type))}</p></div><span class="status status--${c.length?'conflict':'pending'}">${c.length?'! Conflict':'Pending'}</span></div>${c.length?conflictBoxHTML(c,'Contact the affected teacher and resolve the booking before approval.'):'<div class="info-box compact">No scheduling conflict detected.</div>'}<div class="list-item__actions"><button class="button button--secondary" data-view="${r.id}">View / Edit</button><button class="button button--success" data-approve="${r.id}" ${c.length?'disabled':''}>Approve</button><button class="button button--danger" data-reject="${r.id}">Reject</button></div></article>`;}).join('')}</div>`:'<div class="empty-state">No pending requests.</div>';target.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>openRequestDetail(b.dataset.view)));target.querySelectorAll('[data-approve]').forEach(b=>b.addEventListener('click',()=>updateRequestStatus(b.dataset.approve,'Approved')));target.querySelectorAll('[data-reject]').forEach(b=>b.addEventListener('click',()=>updateRequestStatus(b.dataset.reject,'Rejected')));}
function applyApprovedAmendment(r,requestArray){
  if(r.original_kind==='baseline'){
    const actions=sessionActions(),existing=actions[r.original_id]||{},original=getEntry('baseline',r.original_id);actions[r.original_id]={...existing,allocation_key:original?.original_key||existing.allocation_key,original_date:original?.original_date||existing.original_date,date:requestDate(r),lab:r.lab,start_time:r.start_time,end_time:r.end_time,updated_at:new Date().toLocaleString('en-SG')};writeLocal('sasj-v07-session-actions',actions);
  }else if(r.original_kind==='request'){
    const orig=requestArray.find(x=>x.id===r.original_id);if(orig)Object.assign(orig,{date:requestDate(r),week:weekParityFromDate(requestDate(r)),day:dayCodeFromDate(requestDate(r)),lab:r.lab,start_time:r.start_time,end_time:r.end_time});
  }
}
function updateRequestStatus(id,status){
  const arr=requests(),r=arr.find(x=>x.id===id);if(!r)return;
  if(status==='Approved'){const conflicts=conflictsForPending(r);if(conflicts.length){modal('Cannot approve booking',conflictBoxHTML(conflicts,'The existing booking must be changed or cancelled first. The app will never allow two confirmed bookings to occupy the same lab/time.'));return;}if(r.request_type==='amendment')applyApprovedAmendment(r,arr);}
  r.status=status;r.reviewed_by=ROLE_LABELS[APP.role];r.reviewed_at=new Date().toLocaleString('en-SG');writeLocal('sasj-v07-requests',arr);recordAudit(`Request ${status}`,`${r.class_name||r.teacher} · ${r.lab} · ${r.date||''}`);toast(`Request ${status.toLowerCase()}.`);if(APP.page==='approvals')drawApprovals();if(APP.page==='schedule'){drawSchedule();drawBookingStatus();}
}

function renderInventory(){
  const content=document.getElementById('page-content'); content.innerHTML=`<div class="page-actions page-actions--equal">${roleCanEditInventory()?'<button class="button button--primary" id="add-inventory">+ Add Inventory Item</button><button class="button button--secondary" id="inventory-stocktake">Stocktake Mode</button>':''}<button class="button button--secondary" id="inventory-export">Export Audit CSV</button></div><section class="card"><div class="card__body"><div class="filter-grid inventory-filters"><label class="field"><span>Search inventory</span><input id="inv-search" placeholder="Item, component, lab, cabinet..."></label><label class="field"><span>Lab</span><select id="inv-lab"><option>All</option><option>Lab 1</option><option>Lab 2</option></select></label><label class="field"><span>Condition</span><select id="inv-condition"><option>All</option><option>Good</option><option>Incomplete</option><option>Low Stock</option><option>Needs Attention</option><option>Damaged</option><option>Missing</option></select></label></div><div id="inventory-results"></div></div></section>`;
  document.getElementById('add-inventory')?.addEventListener('click',()=>openInventoryEditor());document.getElementById('inventory-stocktake')?.addEventListener('click',openStocktake);document.getElementById('inventory-export').addEventListener('click',exportInventory);['inv-search','inv-lab','inv-condition'].forEach(id=>document.getElementById(id).addEventListener(id==='inv-search'?'input':'change',drawInventory));drawInventory();
}
function openStocktake(){if(!roleCanEditInventory())return;modal('Inventory Stocktake',`<div class="stack"><p class="small">Designed for Mr Kreshna's phone. Check each item and adjust only where the physical count differs.</p><label class="field"><span>Lab</span><select id="stocktake-lab"><option>Lab 1</option><option>Lab 2</option></select></label><div id="stocktake-items"></div></div>`,`<button class="button button--ghost" data-close-modal>Close</button><button class="button button--primary" id="stocktake-complete">Complete Stocktake</button>`);const draw=()=>{const lab=document.getElementById('stocktake-lab').value,items=inventory().filter(i=>i.active!==false&&i.lab===lab);document.getElementById('stocktake-items').innerHTML=items.map(i=>`<div class="stocktake-row"><div><strong>${esc(i.name)}</strong><div class="small">Expected ${i.expected_quantity}</div></div><label class="field compact-field"><span>Count</span><input type="number" min="0" data-stock-id="${i.id}" value="${i.current_quantity}"></label></div>`).join('')||'<div class="empty-state">No items in this lab.</div>';};document.getElementById('stocktake-lab').addEventListener('change',draw);draw();document.getElementById('stocktake-complete').addEventListener('click',()=>{const arr=inventory();document.querySelectorAll('[data-stock-id]').forEach(inp=>{const i=arr.find(x=>x.id===inp.dataset.stockId);if(i)i.current_quantity=Number(inp.value||0);});writeLocal('sasj-v07-inventory',arr);recordAudit('Inventory stocktake completed',document.getElementById('stocktake-lab').value);closeModal();toast('Stocktake saved.');drawInventory();});}
function inventorySearchBlob(i){return JSON.stringify(i).toLowerCase();}
function drawInventory(){const q=(document.getElementById('inv-search')?.value||'').toLowerCase(),lab=document.getElementById('inv-lab')?.value||'All',cond=document.getElementById('inv-condition')?.value||'All';const arr=inventory().filter(i=>i.active!==false&&(lab==='All'||i.lab===lab)&&(cond==='All'||i.condition===cond)&&inventorySearchBlob(i).includes(q));const target=document.getElementById('inventory-results');target.innerHTML=arr.length?`<div class="inventory-grid">${arr.map(inventoryCard).join('')}</div>`:'<div class="empty-state">No inventory item matches your search.</div>';target.querySelectorAll('[data-inv-id]').forEach(b=>b.addEventListener('click',()=>openInventoryDetail(b.dataset.invId)));}
function inventoryCard(i){const missing=(i.components||[]).reduce((s,c)=>s+Math.max(0,(c.expected||0)-(c.current||0)),0);return`<button class="card inventory-card" data-inv-id="${i.id}"><div class="inventory-photo">${i.photo?`<img src="${i.photo}" alt="${esc(i.name)}">`:'Photo optional'}</div><div><h3>${esc(i.name)}</h3><div class="inventory-meta">${esc(i.lab)} · ${esc(i.location||'No location')}</div></div><div><span class="status status--${i.condition==='Good'?'good':i.condition==='Incomplete'?'pending':'conflict'}">${esc(i.condition)}</span>${missing?` <span class="status status--missing">${missing} component${missing===1?'':'s'} missing</span>`:''}</div></button>`;}
function openInventoryDetail(id){const i=inventory().find(x=>x.id===id);if(!i)return;const components=(i.components||[]).length?`<div class="component-list">${i.components.map(c=>`<div class="component-row component-row--view"><span>${esc(c.name)}</span><span>${c.current}/${c.expected}${c.damaged?` · ${c.damaged} damaged`:''}</span></div>`).join('')}</div>`:'<p class="small">No component-level tracking for this item.</p>';modal(i.name,`<div class="stack"><div class="inventory-photo inventory-photo--detail">${i.photo?`<img src="${i.photo}" alt="${esc(i.name)}">`:'No photo uploaded'}</div><div><span class="status status--info">${esc(i.lab)}</span> <span class="status status--pending">${esc(i.condition)}</span><p class="small">${esc(i.location||'Location not set')}</p></div><div><strong>Category:</strong> ${esc(i.category||'Others')}</div><div><strong>Quantity:</strong> ${i.current_quantity} / ${i.expected_quantity}${i.damaged_quantity?` · ${i.damaged_quantity} damaged`:''}</div><div><strong>Components</strong><p class="small">Useful for multi-piece kits like First Aid kit and Sparkle Kits.</p>${components}</div><div><strong>Notes</strong><p class="small">${esc(i.notes||'No notes')}</p></div>${roleCanEditInventory()?'<button class="button button--primary button--wide" id="edit-inventory-detail">Edit / Update Inventory</button>':''}</div>`);document.getElementById('edit-inventory-detail')?.addEventListener('click',()=>{closeModal();openInventoryEditor(i.id);});}
function openInventoryEditor(id){
  const arr=inventory(),existing=arr.find(x=>x.id===id)||{id:uid('inv'),name:'',category:'Apparatus',lab:'Lab 1',location:'',expected_quantity:1,current_quantity:1,damaged_quantity:0,condition:'Good',notes:'',photo:null,components:[],history:[],active:true}; const categories=['Apparatus','Expendables','Sparkle Kit','Others'];
  modal(existing.name?'Edit Inventory Item':'Add Inventory Item',`<div class="form-grid inventory-editor-grid"><label class="field"><span>Name</span><input id="inv-edit-name" value="${esc(existing.name)}"></label><label class="field"><span>Category</span><select id="inv-edit-category">${categories.map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field"><span>Lab</span><select id="inv-edit-lab"><option>Lab 1</option><option>Lab 2</option></select></label><label class="field"><span>Storage location</span><input id="inv-edit-location" value="${esc(existing.location)}"></label><label class="field"><span>Expected quantity</span><input id="inv-edit-expected" type="number" min="0" value="${existing.expected_quantity}"></label><label class="field"><span>Current quantity</span><input id="inv-edit-current" type="number" min="0" value="${existing.current_quantity}"></label><label class="field"><span>Damaged</span><input id="inv-edit-damaged" type="number" min="0" value="${existing.damaged_quantity||0}"></label><label class="field"><span>Condition</span><select id="inv-edit-condition">${['Good','Incomplete','Low Stock','Needs Attention','Damaged','Missing'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field span-2"><span>Notes</span><textarea id="inv-edit-notes">${esc(existing.notes||'')}</textarea></label><label class="field span-2"><span>Photo (camera or gallery)</span><input id="inv-edit-photo" type="file" accept="image/*" capture="environment"><small>Photos are heavily compressed on-device before storage.</small></label><div class="span-2 component-editor-section"><strong>Components</strong><p class="small">Useful for multi-piece kits like First Aid kit and Sparkle Kits.</p><div class="component-column-headings"><span>Component name</span><span>Expected</span><span>Current</span><span>Damaged</span><span></span></div><div id="component-editor" class="component-list"></div><button class="button button--secondary" id="add-component">+ Add Component</button></div></div>`,`<button class="button button--ghost" data-close-modal>Cancel</button><button class="button button--primary" id="save-inventory">Save</button>`);
  document.getElementById('inv-edit-category').value=categories.includes(existing.category)?existing.category:'Others';document.getElementById('inv-edit-lab').value=existing.lab;document.getElementById('inv-edit-condition').value=existing.condition;const working=clone(existing.components||[]);
  const sync=()=>working.forEach((c,idx)=>{const n=document.querySelector(`[data-c-name="${idx}"]`);if(n){c.name=n.value;c.expected=Number(document.querySelector(`[data-c-exp="${idx}"]`).value||0);c.current=Number(document.querySelector(`[data-c-cur="${idx}"]`).value||0);c.damaged=Number(document.querySelector(`[data-c-dmg="${idx}"]`).value||0);}});
  const draw=()=>{document.getElementById('component-editor').innerHTML=working.map((c,idx)=>`<div class="component-editor-row"><label><span>Component name</span><input data-c-name="${idx}" value="${esc(c.name)}"></label><label><span>Expected</span><input data-c-exp="${idx}" type="number" min="0" value="${c.expected||0}"></label><label><span>Current</span><input data-c-cur="${idx}" type="number" min="0" value="${c.current||0}"></label><label><span>Damaged</span><input data-c-dmg="${idx}" type="number" min="0" value="${c.damaged||0}"></label><button class="icon-button text-danger" data-c-del="${idx}" title="Remove component">×</button></div>`).join('');document.querySelectorAll('[data-c-del]').forEach(b=>b.addEventListener('click',()=>{sync();working.splice(Number(b.dataset.cDel),1);draw();}));};draw();document.getElementById('add-component').addEventListener('click',()=>{sync();working.push({name:'',expected:1,current:1,damaged:0});draw();});
  let newPhoto=existing.photo;document.getElementById('inv-edit-photo').addEventListener('change',async e=>{const f=e.target.files[0];if(f){newPhoto=await compressImage(f,settings().photo_max_dimension||1000,settings().photo_quality||.62);toast('Photo compressed and ready.');}});
  document.getElementById('save-inventory').addEventListener('click',()=>{sync();existing.name=document.getElementById('inv-edit-name').value.trim();if(!existing.name){toast('Enter an item name.');return;}Object.assign(existing,{category:document.getElementById('inv-edit-category').value,lab:document.getElementById('inv-edit-lab').value,location:document.getElementById('inv-edit-location').value.trim(),expected_quantity:Number(document.getElementById('inv-edit-expected').value||0),current_quantity:Number(document.getElementById('inv-edit-current').value||0),damaged_quantity:Number(document.getElementById('inv-edit-damaged').value||0),condition:document.getElementById('inv-edit-condition').value,notes:document.getElementById('inv-edit-notes').value.trim(),components:working,photo:newPhoto});existing.history=existing.history||[];existing.history.unshift({when:new Date().toLocaleString('en-SG'),who:ROLE_LABELS[APP.role],change:'Inventory record updated.'});const idx=arr.findIndex(x=>x.id===existing.id);if(idx>=0)arr[idx]=existing;else arr.unshift(existing);writeLocal('sasj-v07-inventory',arr);recordAudit('Inventory updated',`${existing.name} · ${existing.lab}`);closeModal();toast('Inventory saved.');drawInventory();});
}
async function compressImage(file,maxDim,quality){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onload=()=>{let w=img.width,h=img.height;const scale=Math.min(1,maxDim/Math.max(w,h));w=Math.round(w*scale);h=Math.round(h*scale);const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);resolve(canvas.toDataURL('image/jpeg',quality));};img.onerror=reject;img.src=reader.result;};reader.readAsDataURL(file);});}
function exportInventory(){const rows=[['Name','Category','Lab','Location','Expected','Current','Damaged','Condition','Notes']];inventory().filter(i=>i.active!==false).forEach(i=>rows.push([i.name,i.category,i.lab,i.location,i.expected_quantity,i.current_quantity,i.damaged_quantity||0,i.condition,i.notes||'']));const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');downloadText('sasj_inventory_audit.csv',csv,'text/csv');}
function downloadText(name,text,type){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}

function renderTimetable(){
  const content=document.getElementById('page-content'),s=data().baseline_schedule.summary;content.innerHTML=`<div class="demo-banner"><strong>Core function:</strong> production will run the timetable parser + optimiser online. This public prototype demonstrates the upload → validate → generate → review → publish workflow without sending timetable files anywhere.</div><div class="cards"><div class="card metric"><div class="metric__label">Current pre-assigned sessions</div><div class="metric__value">${s.sessions}</div><div class="metric__hint">Current P3–P5 school baseline</div></div><div class="card metric"><div class="metric__label">Classes with 2 sessions</div><div class="metric__value">${s.classes_with_2_sessions}</div><div class="metric__hint">Out of 18 active P3–P5 classes</div></div><div class="card metric"><div class="metric__label">Future parser scope</div><div class="metric__value">24</div><div class="metric__hint">Mainstream P3–P6 classes</div></div><div class="card metric"><div class="metric__label">Preferred buffer</div><div class="metric__value">30m</div><div class="metric__hint">One period where feasible</div></div></div><section class="card" style="margin-top:16px"><div class="card__header"><div><h2>Import new class timetable</h2><p class="small">Accept Excel, PDF, multiple files, or ZIP bundles. Uncertain extraction is reviewed rather than guessed.</p></div></div><div class="card__body"><div class="form-grid timetable-import-grid"><label class="field span-2"><span>Timetable files</span><input id="tt-files" type="file" accept=".zip,.xlsx,.xls,.xlsm,.pdf" multiple></label><label class="field"><span>Version name</span><input id="tt-version" value="2026 Update 5"></label><label class="field"><span>Effective date</span><input id="tt-effective" type="date"></label></div><div class="page-actions page-actions--equal" style="margin-top:14px"><button class="button button--primary" id="tt-generate">Analyse & Generate Proposal</button><button class="button button--secondary" id="tt-review-current">Review Current Baseline</button></div><div id="tt-result"></div></div></section><section class="card" style="margin-top:16px"><div class="card__header"><h2>Allocation rules</h2></div><div class="card__body"><ul><li>Two consecutive 30-minute Science periods form the normal one-hour booking.</li><li>Target 1 Odd + 1 Even per mainstream class; use 2+0 only when needed.</li><li>Lab 1 prefers P3/P4; Lab 2 prefers P5/P6, but this is flexible.</li><li>Current published baseline excludes P6 for the PSLE period; future generation still supports P3–P6.</li><li>Prefer one 30-minute empty period between classes in the same lab when feasible.</li><li>Support, Enrichment and Foundation groups are excluded from baseline generation and may book ad hoc.</li><li>HOD/SH or System Admin reviews the proposal before publication.</li></ul></div></section>`;document.getElementById('tt-generate').addEventListener('click',runTimetableUpload);document.getElementById('tt-review-current').addEventListener('click',()=>showScheduleReview(data().baseline_schedule));
}
function runTimetableUpload(){const files=[...document.getElementById('tt-files').files],target=document.getElementById('tt-result');if(!files.length){target.innerHTML='<div class="warning-box" style="margin-top:12px">Select at least one timetable file or ZIP first.</div>';return;}target.innerHTML=`<div class="workflow-list" style="margin-top:14px"><div class="workflow-step"><span class="workflow-step__num">1</span><div><strong>${files.length} file${files.length===1?'':'s'} selected</strong><div class="small">${files.map(f=>esc(f.name)).join(', ')}</div></div></div><div class="workflow-step"><span class="workflow-step__num">2</span><div><strong>Parser validation</strong><div class="small">Production identifies P3–P6 mainstream Science periods, Odd/Even weeks and ambiguous entries.</div></div></div><div class="workflow-step"><span class="workflow-step__num">3</span><div><strong>Optimisation</strong><div class="small">Fair access, Odd/Even balance, preferred lab and 30-minute turnaround buffer.</div></div></div><div class="workflow-step"><span class="workflow-step__num">4</span><div><strong>Review & publish</strong><div class="small">Nothing becomes live until HOD/SH or System Admin reviews and publishes.</div></div></div></div><div class="page-actions page-actions--equal" style="margin-top:14px"><button class="button button--primary" id="tt-demo-preview">Preview Extracted Data</button><button class="button button--success" id="tt-demo-proposal">Generate Prototype Proposal</button></div><div class="warning-box" style="margin-top:12px"><strong>Public prototype:</strong> files are not uploaded or parsed. Production will run the real backend timetable engine after workflow approval.</div>`;document.getElementById('tt-demo-preview').addEventListener('click',()=>modal('Timetable extraction preview',`<div class="stack"><div class="info-box"><strong>Parser scope:</strong> 24 mainstream P3–P6 class timetables.</div><div class="list-item"><strong>Accepted inputs</strong><p>Single Excel/PDF, multiple files, or ZIP bundles containing Excel/PDF.</p></div><div class="list-item"><strong>Validation</strong><p>Science periods, Odd/Even week, consecutive periods, class names and timetable ambiguities are reviewed before optimisation.</p></div><div class="list-item"><strong>Current operational exception</strong><p>P6 is excluded from the current published baseline during the PSLE period, but remains supported by the scheduler.</p></div></div>`));document.getElementById('tt-demo-proposal').addEventListener('click',()=>showScheduleReview(data().baseline_schedule));}
function showScheduleReview(schedule){modal('Current school baseline review',`<div class="cards two-card-grid"><div class="card metric"><div class="metric__label">Sessions</div><div class="metric__value">${schedule.summary.sessions}</div></div><div class="card metric"><div class="metric__label">Cross-lab</div><div class="metric__value">${schedule.summary.cross_lab_sessions}</div></div></div><div class="stack" style="margin-top:14px"><strong>Exceptions / explanations</strong>${schedule.exceptions.map(e=>`<div class="list-item">${esc(e.message)}</div>`).join('')||'<div class="info-box">No exceptions.</div>'}</div>`);}

function renderRoster(){const content=document.getElementById('page-content');content.innerHTML=`<div class="page-actions page-actions--equal"><button class="button button--primary" id="roster-import">Import Deployment CSV</button><button class="button button--secondary" id="special-group-add">+ Add Special Group</button><button class="button button--secondary" id="deployment-export">Export Deployment CSV</button></div><input id="roster-file" type="file" accept=".csv" hidden><section id="deployment-summary"></section><section id="roster-results"></section><section class="card" style="margin-top:16px"><div class="card__header"><div><h2>Special / non-mainstream groups</h2><p class="small">Ad hoc classes, pullout groups, supplementary classes, E2K and workshops can use the labs without entering the mainstream baseline allocation.</p></div></div><div class="card__body" id="special-group-results"></div></section>`;document.getElementById('roster-import').addEventListener('click',()=>document.getElementById('roster-file').click());document.getElementById('roster-file').addEventListener('change',importRosterCsv);document.getElementById('special-group-add').addEventListener('click',()=>editSpecialGroup());document.getElementById('deployment-export').addEventListener('click',exportDeployment);drawRoster();}
function teacherLevels(t){return [...new Set((t.classes||[]).map(c=>(c.match(/^P([3-6])\b/)||[])[1]).filter(Boolean).map(n=>`P${n}`))];}
function deploymentWarnings(){const classes=data().organizer_classes||data().classes;const ts=teachers().filter(t=>t.active!==false);const warnings=[];classes.forEach(c=>{const linked=ts.filter(t=>(t.classes||[]).includes(c));if(!linked.length)warnings.push(`${c}: no Science teacher linked`);if(linked.length>2)warnings.push(`${c}: more than two teachers linked`);});return warnings;}
function drawRoster(){const target=document.getElementById('roster-results'),summary=document.getElementById('deployment-summary'),ts=teachers().filter(t=>t.active!==false),levels=['P3','P4','P5','P6'],warnings=deploymentWarnings();summary.innerHTML=`<div class="cards deployment-summary">${levels.map(level=>{const count=ts.filter(t=>teacherLevels(t).includes(level)).length;const cls=(data().organizer_classes||[]).filter(c=>c.startsWith(level+' ')).length;return `<div class="card metric"><div class="metric__label">${level} Science</div><div class="metric__value">${count}</div><div class="metric__hint">teachers across ${cls} mainstream classes</div></div>`;}).join('')}</div>${warnings.length?`<div class="warning-box"><strong>Deployment checks</strong><br>${warnings.map(esc).join('<br>')}</div>`:'<div class="info-box"><strong>Deployment check:</strong> all mainstream P3–P6 classes have at least one linked Science teacher.</div>'}`;target.innerHTML=levels.map(level=>{const levelTeachers=ts.filter(t=>teacherLevels(t).includes(level));return `<section class="card deployment-level"><div class="card__header"><div><h2>${level} Science</h2><p class="small">${levelTeachers.length} teacher${levelTeachers.length===1?'':'s'} deployed to this level</p></div></div><div class="card__body"><div class="roster-grid">${levelTeachers.map(t=>teacherDeploymentCard(t,level)).join('')||'<div class="empty-state">No teacher assigned.</div>'}</div></div></section>`;}).join('')+`<section class="card deployment-level"><div class="card__header"><div><h2>Other / currently unlinked Science staff</h2><p class="small">Science teachers without a mainstream P3–P6 class link can still be assigned to special groups.</p></div></div><div class="card__body"><div class="roster-grid">${ts.filter(t=>!teacherLevels(t).length).map(t=>teacherDeploymentCard(t,'')).join('')||'<div class="empty-state">None.</div>'}</div></div></section>`;target.querySelectorAll('[data-teacher-id]').forEach(b=>b.addEventListener('click',()=>editTeacher(b.dataset.teacherId)));drawSpecialGroups();}
function teacherDeploymentCard(t,level){const cls=(t.classes||[]).filter(c=>!level||c.startsWith(level+' '));return `<button class="card roster-card" data-teacher-id="${t.id}"><div class="roster-card__top"><h3>${esc(t.name)}</h3>${(t.roles||[]).includes('science_hod')?'<span class="status status--info">HOD / SH</span>':''}</div><div class="roster-card__email">${esc(t.email||'No email')}</div><div class="tag-list">${cls.length?cls.map(c=>`<span class="tag">${esc(c)}</span>`).join(''):'<span class="tag">No mainstream class</span>'}</div></button>`;}
function editTeacher(id){const arr=teachers(),t=arr.find(x=>x.id===id);if(!t)return;const allClasses=data().organizer_classes||data().classes,classBoxes=allClasses.map(c=>`<label class="class-link-option"><input type="checkbox" data-class-link="${esc(c)}" ${(t.classes||[]).includes(c)?'checked':''}> ${esc(c)}</label>`).join('');modal(`Edit ${t.name}`,`<div class="stack"><label class="field"><span>Email</span><input id="teacher-email" value="${esc(t.email||'')}"></label><div><strong>Linked mainstream classes</strong><p class="small">A mainstream class can be linked to a maximum of two Science teachers. A teacher may appear under several levels.</p><div class="class-link-grid">${classBoxes}</div></div></div>`,`<button class="button button--ghost" data-close-modal>Cancel</button><button class="button button--primary" id="save-teacher">Save</button>`);document.getElementById('save-teacher').addEventListener('click',()=>{const selected=[...document.querySelectorAll('[data-class-link]:checked')].map(x=>x.dataset.classLink),others=arr.filter(x=>x.id!==id);for(const c of selected){if(others.filter(x=>(x.classes||[]).includes(c)).length>=2){toast(`${c} already has two linked teachers.`);return;}}t.email=document.getElementById('teacher-email').value.trim();t.classes=selected;writeLocal('sasj-v07-teachers',arr);recordAudit('Teacher deployment updated',t.name);closeModal();toast('Teacher deployment updated.');drawRoster();});}
function importRosterCsv(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const lines=reader.result.split(/\r?\n/).filter(Boolean);if(lines.length<2){toast('CSV appears empty.');return;}const header=lines[0].split(',').map(x=>x.trim().toLowerCase()),ni=header.indexOf('teacher_name'),ei=header.indexOf('email'),ci=header.indexOf('class');if(ni<0||ei<0||ci<0){toast('CSV needs teacher_name,email,class columns.');return;}const map=new Map();for(const line of lines.slice(1)){const cols=line.split(',').map(x=>x.trim());if(!cols[ni])continue;const key=cols[ni];if(!map.has(key))map.set(key,{id:key.toLowerCase().replace(/\s+/g,'-'),name:key,email:cols[ei],classes:[],roles:['science_teacher'],active:true});if(cols[ci]&&(data().organizer_classes||data().classes).includes(cols[ci]))map.get(key).classes.push(cols[ci]);}writeLocal('sasj-v07-teachers',[...map.values()]);recordAudit('Teacher deployment CSV imported',file.name);toast('Deployment CSV imported. Review class links.');drawRoster();};reader.readAsText(file);}
function drawSpecialGroups(){const box=document.getElementById('special-group-results');if(!box)return;const groups=specialGroups().filter(g=>g.active!==false);box.innerHTML=groups.length?`<div class="special-group-grid">${groups.map(g=>`<button class="card special-group-card" data-special-id="${g.id}"><div><span class="status status--info">${esc(g.type)}</span><h3>${esc(g.name)}</h3><p class="small">${esc(g.level||'Multi-level')} · ${esc(g.semester||'Ad hoc')} · ${esc(g.lab_requirement||'As booked')}</p></div><div class="tag-list">${(g.teachers||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')||'<span class="tag">Teacher not assigned</span>'}</div></button>`).join('')}</div>`:'<div class="empty-state">No special groups created.</div>';box.querySelectorAll('[data-special-id]').forEach(b=>b.addEventListener('click',()=>editSpecialGroup(b.dataset.specialId)));}
function editSpecialGroup(id=''){const arr=specialGroups(),g=arr.find(x=>x.id===id)||{id:uid('group'),name:'',type:'Ad hoc class',level:'P6',teachers:[],semester:'Semester 1',lab_requirement:'As booked',notes:'',active:true};const types=['Ad hoc class','Pullout','Supplementary','E2K','Workshop','Other'];modal(id?'Edit Special Group':'Create Special Group',`<div class="form-grid"><label class="field"><span>Group / programme name</span><input id="sg-name" value="${esc(g.name)}" placeholder="e.g. P6 Supplementary Science"></label><label class="field"><span>Type</span><select id="sg-type">${types.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>Level</span><select id="sg-level"><option>P3</option><option>P4</option><option>P5</option><option>P6</option><option>Multi-level</option></select></label><label class="field"><span>Period</span><select id="sg-sem"><option>Semester 1</option><option>Semester 2</option><option>Term-based</option><option>Ad hoc</option></select></label><label class="field"><span>Primary teacher</span><select id="sg-teacher1"><option value="">Unassigned</option>${teachers().filter(t=>t.active!==false).map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></label><label class="field"><span>Co-teacher (optional)</span><select id="sg-teacher2"><option value="">None</option>${teachers().filter(t=>t.active!==false).map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></label><label class="field"><span>Lab requirement</span><select id="sg-lab"><option>As booked</option><option>Lab 1</option><option>Lab 2</option><option>Both labs</option></select></label><label class="field span-2"><span>Notes</span><textarea id="sg-notes">${esc(g.notes||'')}</textarea></label></div>`,`<button class="button button--ghost" data-close-modal>Cancel</button><button class="button button--primary" id="sg-save">Save Group</button>`);[['sg-type',g.type],['sg-level',g.level],['sg-sem',g.semester],['sg-lab',g.lab_requirement],['sg-teacher1',(g.teachers||[])[0]||''],['sg-teacher2',(g.teachers||[])[1]||'']].forEach(([i,v])=>{const el=document.getElementById(i);if(el)el.value=v;});document.getElementById('sg-save').addEventListener('click',()=>{g.name=document.getElementById('sg-name').value.trim();if(!g.name){toast('Enter a group name.');return;}g.type=document.getElementById('sg-type').value;g.level=document.getElementById('sg-level').value;g.semester=document.getElementById('sg-sem').value;g.lab_requirement=document.getElementById('sg-lab').value;g.notes=document.getElementById('sg-notes').value.trim();g.teachers=[document.getElementById('sg-teacher1').value,document.getElementById('sg-teacher2').value].filter(Boolean);const idx=arr.findIndex(x=>x.id===g.id);if(idx>=0)arr[idx]=g;else arr.push(g);writeLocal('sasj-v07-special-groups',arr);recordAudit('Special group updated',g.name);closeModal();toast('Special group saved.');drawSpecialGroups();});}
function exportDeployment(){const rows=[['Teacher','Email','Classes','Levels']];teachers().filter(t=>t.active!==false).forEach(t=>rows.push([t.name,t.email||'',(t.classes||[]).join('; '),teacherLevels(t).join('; ')]));specialGroups().filter(g=>g.active!==false).forEach(g=>rows.push([`[${g.type}] ${g.name}`,'',(g.teachers||[]).join('; '),g.level||'']));downloadText('sasj_teacher_deployment.csv',rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');}

function renderSettings(){const s=settings(),content=document.getElementById('page-content');content.innerHTML=`<section class="card"><div class="card__header"><h2>Operational rules</h2></div><div class="card__body"><div class="form-grid admin-settings-grid"><label class="field"><span>Pre-assigned confirmation deadline</span><input id="set-deadline" type="time" value="${esc(s.confirmation_deadline)}"></label><label class="field"><span>Odd Week reference Monday</span><input id="set-odd-reference" type="date" value="${esc(s.odd_week_reference_monday||'2026-09-07')}"></label><label class="field"><span>Preparation buffer</span><select id="set-buffer"><option value="30">30 minutes (1 period)</option><option value="0">No preferred buffer</option></select></label><label class="field"><span>Photo maximum dimension</span><select id="set-photo"><option value="800">800 px</option><option value="1000">1000 px</option><option value="1200">1200 px</option></select></label><label class="field"><span>Email confirmation reminder</span><select id="set-email"><option value="false">Planned / not active in prototype</option><option value="true">Enable in production when email service is configured</option></select></label></div><div class="warning-box" style="margin-top:14px">Auto-release applies <strong>only</strong> to pre-assigned recurring sessions that remain unconfirmed by the previous-day deadline. Approved ad-hoc, workshop, event and PSLE bookings are not auto-released.</div><div class="page-actions page-actions--equal" style="margin-top:14px"><button class="button button--primary" id="save-settings">Save Prototype Settings</button></div></div></section><section class="card" style="margin-top:16px"><div class="card__header"><div><h2>MOE Primary School Academic Calendar</h2><p class="small">Preloaded 2026 and 2027 term/vacation dates. School-specific closure dates can be added separately below.</p></div></div><div class="card__body"><label class="field calendar-year-select"><span>Academic year</span><select id="calendar-year"><option>2026</option><option>2027</option></select></label><div id="calendar-summary"></div></div></section><section class="card" style="margin-top:16px"><div class="card__header"><div><h2>Lab block-out dates</h2><p class="small">Use for PSLE arrangements, examinations, maintenance or school events. Blocked labs cannot accept confirmed bookings.</p></div><button class="button button--primary" id="add-blockout">+ Add Block-out</button></div><div class="card__body" id="blockout-list"></div></section><section class="card" style="margin-top:16px"><div class="card__header"><div><h2>Audit trail</h2><p class="small">Recent prototype changes. Production will store the full history in the shared database.</p></div><button class="button button--secondary" id="export-all-data">Export Prototype Data</button></div><div class="card__body" id="audit-list"></div></section><section class="card prototype-controls"><div class="card__header"><h2>Prototype controls</h2></div><div class="card__body"><p class="small">Restore the original requests, inventory, deployment and confirmation states after a demonstration.</p><button class="button button--danger" id="reset-demo">Reset All Demo Data</button></div></section>`;document.getElementById('set-buffer').value=String(s.buffer_period_minutes);document.getElementById('set-photo').value=String(s.photo_max_dimension);document.getElementById('set-email').value=String(s.email_reminders_enabled);document.getElementById('save-settings').addEventListener('click',()=>{s.confirmation_deadline=document.getElementById('set-deadline').value;s.odd_week_reference_monday=document.getElementById('set-odd-reference').value;s.buffer_period_minutes=Number(document.getElementById('set-buffer').value);s.photo_max_dimension=Number(document.getElementById('set-photo').value);s.email_reminders_enabled=document.getElementById('set-email').value==='true';writeLocal('sasj-v07-settings',s);recordAudit('Administration settings updated','Operational rules');toast('Prototype settings saved.');});const yearSelect=document.getElementById('calendar-year');yearSelect.value=String(parseISODate(APP.schedule.date).getFullYear()) in (data().academic_calendars||{})?String(parseISODate(APP.schedule.date).getFullYear()):'2026';yearSelect.addEventListener('change',drawAcademicCalendar);drawAcademicCalendar();document.getElementById('add-blockout').addEventListener('click',()=>editBlockout());drawBlockouts();drawAudit();document.getElementById('export-all-data').addEventListener('click',exportPrototypeData);document.getElementById('reset-demo').addEventListener('click',()=>{if(!confirm('Reset all browser-local prototype changes?'))return;clearPrototypeData();toast('Prototype data reset.');navigate('dashboard');});}
function drawAcademicCalendar(){const year=document.getElementById('calendar-year')?.value||'2026',cal=academicCalendar(year),box=document.getElementById('calendar-summary');if(!box||!cal)return;box.innerHTML=`<div class="term-grid">${cal.terms.map(t=>`<div class="calendar-term"><strong>${esc(t.name)}</strong><span>${formatDateShort(t.start)} – ${formatDateShort(t.end)}</span></div>`).join('')}</div><div class="calendar-two-col"><div><h3>School vacations</h3>${cal.vacations.map(v=>`<div class="list-item"><strong>${esc(v.name)}</strong><p>${formatDateShort(v.start)} – ${formatDateShort(v.end)}</p></div>`).join('')}</div><div><h3>Scheduled school holidays</h3>${cal.scheduled_holidays.map(h=>`<div class="list-item"><strong>${esc(h.name)}</strong><p>${formatDateLong(h.date)}</p></div>`).join('')}</div></div><p class="small calendar-source">Source reference: Ministry of Education school calendar. School-specific events and closures should be added as block-outs.</p>`;}
function drawBlockouts(){const box=document.getElementById('blockout-list');if(!box)return;const arr=blockouts().filter(b=>b.active!==false);box.innerHTML=arr.length?arr.map(b=>`<button class="list-item blockout-item" data-blockout-id="${b.id}"><div><strong>${esc(b.reason)}</strong><p>${formatDateShort(b.start_date)} – ${formatDateShort(b.end_date)} · ${esc(b.lab)}</p></div><span class="status status--rejected">Blocked</span></button>`).join(''):'<div class="empty-state">No school-specific lab block-outs have been added.</div>';box.querySelectorAll('[data-blockout-id]').forEach(b=>b.addEventListener('click',()=>editBlockout(b.dataset.blockoutId)));}
function editBlockout(id=''){const arr=blockouts(),b=arr.find(x=>x.id===id)||{id:uid('block'),reason:'',start_date:APP.schedule.date,end_date:APP.schedule.date,lab:'Both',active:true};modal(id?'Edit Lab Block-out':'Add Lab Block-out',`<div class="form-grid"><label class="field span-2"><span>Reason</span><input id="block-reason" value="${esc(b.reason)}" placeholder="e.g. PSLE arrangements"></label><label class="field"><span>Start date</span><input id="block-start" type="date" value="${b.start_date}"></label><label class="field"><span>End date</span><input id="block-end" type="date" value="${b.end_date}"></label><label class="field"><span>Lab</span><select id="block-lab"><option>Both</option><option>Lab 1</option><option>Lab 2</option></select></label></div>`,`<button class="button button--ghost" data-close-modal>Cancel</button>${id?'<button class="button button--danger" id="block-remove">Remove</button>':''}<button class="button button--primary" id="block-save">Save Block-out</button>`);document.getElementById('block-lab').value=b.lab;document.getElementById('block-save').addEventListener('click',()=>{b.reason=document.getElementById('block-reason').value.trim();if(!b.reason){toast('Enter a reason.');return;}b.start_date=document.getElementById('block-start').value;b.end_date=document.getElementById('block-end').value;b.lab=document.getElementById('block-lab').value;if(b.end_date<b.start_date){toast('End date cannot be before start date.');return;}const idx=arr.findIndex(x=>x.id===b.id);if(idx>=0)arr[idx]=b;else arr.push(b);writeLocal('sasj-v07-blockouts',arr);recordAudit('Lab block-out saved',`${b.reason} · ${b.lab}`);closeModal();drawBlockouts();toast('Lab block-out saved.');});document.getElementById('block-remove')?.addEventListener('click',()=>{b.active=false;writeLocal('sasj-v07-blockouts',arr);recordAudit('Lab block-out removed',b.reason);closeModal();drawBlockouts();});}
function drawAudit(){const box=document.getElementById('audit-list');if(!box)return;const arr=auditLogs().slice(0,20);box.innerHTML=arr.length?arr.map(a=>`<div class="audit-row"><div><strong>${esc(a.action)}</strong><p>${esc(a.detail||'')}</p></div><div class="small">${esc(a.when)}<br>${esc(a.who)}</div></div>`).join(''):'<div class="empty-state">No audit entries yet.</div>';}
function exportPrototypeData(){const payload={exported_at:new Date().toISOString(),teachers:teachers(),special_groups:specialGroups(),requests:requests(),inventory:inventory(),blockouts:blockouts(),audit:auditLogs(),settings:settings()};downloadText('sasj_science_lab_prototype_backup.json',JSON.stringify(payload,null,2),'application/json');}

function modal(title,body,footer=''){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><header class="modal__header"><h2>${esc(title)}</h2><button class="icon-button" data-close-modal>×</button></header><div class="modal__body">${body}</div>${footer?`<footer class="modal__footer">${footer}</footer>`:''}</section></div>`;root.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',closeModal));root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();});}
function closeModal(){document.getElementById('modal-root').innerHTML='';}

if('serviceWorker' in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js').catch(()=>{}));
init();
